def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parseTime(text):
        return int(text[:2]) * 60 + int(text[3:5])

    def parseOffset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def formatTime(value):
        hour = value // 60
        minute = value - hour * 60
        if hour < 10:
            hourText = "0" + str(hour)
        else:
            hourText = str(hour)
        if minute < 10:
            minuteText = "0" + str(minute)
        else:
            minuteText = str(minute)
        return hourText + ":" + minuteText

    def ceilQuarter(value):
        return ((value + 14) // 15) * 15

    def cleanInterval(start, end):
        pieces = []
        if end <= start:
            a = max(0, start)
            b = 1440
            if a < b:
                pieces.append((a, b))
            a = 0
            b = min(1440, end)
            if a < b:
                pieces.append((a, b))
        else:
            a = max(0, start)
            b = min(1440, end)
            if a < b:
                pieces.append((a, b))
        return pieces

    def convertInterval(startText, endText, personOffset, userOffset):
        shift = userOffset - personOffset
        start = parseTime(startText) + shift
        end = parseTime(endText) + shift
        return cleanInterval(start, end)

    def inside(start, end, intervals):
        for a, b in intervals:
            if start >= a and end <= b:
                return True
        return False

    def overlaps(start, end, intervals):
        for a, b in intervals:
            if start < b and end > a:
                return True
        return False

    result = {"starts": {}}
    earliestMinutes = 0 if earliest == "" else parseTime(earliest)
    latestMinutes = 1440 if latest_end == "" else parseTime(latest_end)
    people = [""] + attendees

    for day in days:
        userData = api.read_calendar("", day)
        userDays = userData.get("days", [])
        if len(userDays) == 0:
            continue

        dayKey = userDays[0].get("day", day)
        userOffset = parseOffset(userData.get("utc_offset", "+00:00"))

        workByPerson = {}
        busyByPerson = {}
        complete = True

        for person in people:
            data = userData if person == "" else api.read_calendar(person, day)
            entries = data.get("days", [])
            if len(entries) == 0:
                complete = False
                break

            offset = parseOffset(data.get("utc_offset", "+00:00"))
            workHours = data.get("working_hours", "")
            if workHours == "":
                workHours = entries[0].get("working_hours", "00:00-24:00")

            workBits = workHours.split("-")
            workParts = convertInterval(workBits[0], workBits[1], offset, userOffset)

            busyParts = []
            events = entries[0].get("events", [])
            for event in events:
                if event.get("show_as") != "free":
                    parts = convertInterval(event["start"], event["end"], offset, userOffset)
                    for part in parts:
                        busyParts.append(part)

            workByPerson[person] = workParts
            busyByPerson[person] = busyParts

        if not complete:
            continue

        startCandidate = ceilQuarter(max(earliestMinutes, 0))
        lastCandidate = min(latestMinutes - minutes, 1440 - minutes)

        dayStarts = []
        candidate = startCandidate
        while candidate <= lastCandidate:
            endCandidate = candidate + minutes
            ok = True

            for person in people:
                if not inside(candidate, endCandidate, workByPerson[person]):
                    ok = False
                    break
                if overlaps(candidate, endCandidate, busyByPerson[person]):
                    ok = False
                    break

            if ok:
                dayStarts.append(formatTime(candidate))

            candidate += 15

        if len(dayStarts) > 0:
            result["starts"][dayKey] = dayStarts

    return result
