def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    """Find every start time, by day, when the user and all the listed attendees are free for a meeting of the given length. days are mon to fri; earliest is the first allowed start and latest_end the time the meeting must end by, both HH:MM or empty. Returns the workable starts, earliest first."""
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        hour = total // 60
        minute = total % 60
        return str(hour).rjust(2, "0") + ":" + str(minute).rjust(2, "0")

    def parse_offset(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def add_interval(intervals, start, end):
        if start == end:
            return
        if start > end:
            add_interval(intervals, start, 1440)
            add_interval(intervals, 0, end)
            return
        if end <= 0 or start >= 1440:
            return
        if start < 0:
            start = 0
        if end > 1440:
            end = 1440
        if start < end:
            intervals.append([start, end])

    def merge_intervals(intervals):
        if len(intervals) == 0:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0][:]]
        for item in intervals[1:]:
            if item[0] <= merged[-1][1]:
                if item[1] > merged[-1][1]:
                    merged[-1][1] = item[1]
            else:
                merged.append(item[:])
        return merged

    def add_working_as_busy(intervals, start_min, end_min):
        if start_min < end_min:
            add_interval(intervals, 0, start_min)
            add_interval(intervals, end_min, 1440)
        elif start_min > end_min:
            add_interval(intervals, end_min, start_min)
        else:
            return

    if len(days) == 0:
        return {"starts": {}}

    first_data = api.read_calendar("", days[0])
    user_offset = parse_offset(first_data["utc_offset"])
    earliest_min = parse_time(earliest) if earliest != "" else 0
    latest_end_min = parse_time(latest_end) if latest_end != "" else 1440

    result = {"starts": {}}

    for day in days:
        user_data = api.read_calendar("", day)
        if len(user_data["days"]) == 0:
            continue

        day_info = user_data["days"][0]
        day_key = day_info["day"]
        busy = []

        user_work_start, user_work_end = user_data["working_hours"].split("-")
        add_working_as_busy(busy, parse_time(user_work_start), parse_time(user_work_end))

        for event in day_info["events"]:
            if event["show_as"] == "busy":
                add_interval(busy, parse_time(event["start"]), parse_time(event["end"]))

        for person in attendees:
            person_data = api.read_calendar(person, day)
            if len(person_data["days"]) == 0:
                continue

            person_info = person_data["days"][0]
            delta = user_offset - parse_offset(person_data["utc_offset"])

            work_start, work_end = person_data["working_hours"].split("-")
            add_working_as_busy(
                busy,
                parse_time(work_start) + delta,
                parse_time(work_end) + delta
            )

            for event in person_info["events"]:
                if event["show_as"] == "busy":
                    add_interval(
                        busy,
                        parse_time(event["start"]) + delta,
                        parse_time(event["end"]) + delta
                    )

        merged_busy = merge_intervals(busy)
        starts = []
        current = 0

        for item in merged_busy + [[1440, 1440]]:
            free_start = current
            free_end = item[0]
            if free_end > free_start:
                start = max(free_start, earliest_min)
                start = ((start + 14) // 15) * 15
                last_start = min(free_end - minutes, latest_end_min - minutes)
                last_start = (last_start // 15) * 15
                while start <= last_start:
                    if start + minutes <= free_end and start + minutes <= latest_end_min:
                        starts.append(to_time(start))
                    start += 15
            current = item[1]

        if len(starts) > 0:
            result["starts"][day_key] = starts

    return result
