def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_min(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(value):
        value = value % 1440
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def off_min(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def find_day(data, day):
        target = day[:3].lower()
        if "days" in data:
            for item in data["days"]:
                if item.get("day", "")[:3].lower() == target:
                    return item
        return {}

    def buffer_from_note(note):
        if "between any meeting" not in note or "minutes" not in note:
            return 0
        num = ""
        for ch in note:
            if ch >= "0" and ch <= "9":
                num += ch
            elif num != "":
                break
        if num == "":
            return 0
        return int(num)

    def ceil_quarter(value):
        if value <= 0:
            return 0
        q = value // 15
        if value % 15 == 0:
            return q * 15
        return (q + 1) * 15

    starts = {}
    earliest_min = 0 if earliest == "" else to_min(earliest)
    latest_min = 1440 if latest_end == "" else to_min(latest_end)

    for day in days:
        user_data = api.read_calendar("", day)
        user_day = find_day(user_data, day)
        if user_day == {}:
            continue

        user_off = off_min(user_data["utc_offset"])
        low = earliest_min
        high = latest_min

        user_hours = user_data.get("working_hours", "00:00-24:00").split("-")
        user_start = to_min(user_hours[0])
        user_end = to_min(user_hours[1])
        if user_start > low:
            low = user_start
        if user_end < high:
            high = user_end

        blocked = []
        for event in user_day.get("events", []):
            if event.get("show_as", "") == "busy":
                blocked.append((to_min(event["start"]), to_min(event["end"])))

        for person in attendees:
            pdata = api.read_calendar(person, day)
            pday = find_day(pdata, day)
            if pday == {}:
                continue

            poff = off_min(pdata["utc_offset"])
            delta = user_off - poff

            hours = pdata.get("working_hours", "00:00-24:00").split("-")
            p_start = to_min(hours[0]) + delta
            p_end = to_min(hours[1]) + delta
            if p_start > low:
                low = p_start
            if p_end < high:
                high = p_end

            gap = buffer_from_note(pdata.get("note", ""))
            for event in pday.get("events", []):
                if event.get("show_as", "") == "busy":
                    s = to_min(event["start"]) + delta - gap
                    e = to_min(event["end"]) + delta + gap
                    blocked.append((s, e))

        low = max(low, 0)
        high = min(high, 1440)

        start = ceil_quarter(low)
        if start + minutes > high:
            continue

        day_starts = []
        t = start
        while t + minutes <= high:
            ok = True
            for block in blocked:
                if t < block[1] and t + minutes > block[0]:
                    ok = False
                    break
            if ok:
                day_starts.append(to_time(t))
            t += 15

        if len(day_starts) > 0:
            starts[day] = day_starts

    return {"starts": starts}
