def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def time_text(total):
        hours = total // 60
        mins = total % 60
        if hours < 10:
            hs = "0" + str(hours)
        else:
            hs = str(hours)
        if mins < 10:
            ms = "0" + str(mins)
        else:
            ms = str(mins)
        return hs + ":" + ms

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def clip(value, low, high):
        if value < low:
            return low
        if value > high:
            return high
        return value

    def segments(start, end, delta):
        start = start + delta
        end = end + delta
        out = []
        if end <= start:
            if start < 1440:
                a = start
                if a < 0:
                    a = 0
                if a < 1440:
                    out.append((a, 1440))
            if end > 0:
                b = end
                if b > 1440:
                    b = 1440
                if b > 0:
                    out.append((0, b))
        else:
            a = start
            b = end
            if a < 0:
                a = 0
            if b > 1440:
                b = 1440
            if b > a and a < 1440 and b > 0:
                out.append((a, b))
        return out

    wanted = set()
    for day in days:
        wanted.add(str(day).lower())

    order = ["mon", "tue", "wed", "thu", "fri"]
    wanted_days = []
    for day in order:
        if day in wanted:
            wanted_days.append(day)

    if not wanted_days:
        return {"starts": {}}

    user_calendar = api.read_calendar("", "")
    user_offset = parse_offset(user_calendar.get("utc_offset", ""))

    calendars = []
    calendars.append(user_calendar)
    seen = set()
    seen.add("")

    for name in attendees:
        if name in seen:
            continue
        seen.add(name)
        calendars.append(api.read_calendar(name, ""))

    people = []
    for data in calendars:
        delta = user_offset - parse_offset(data.get("utc_offset", ""))
        daymap = dict()
        for entry in data.get("days", []):
            daymap[str(entry.get("day", "")).lower()] = entry

        dayinfo = dict()
        work = data.get("working_hours", "00:00-24:00")
        ws = parse_time(work[0:5])
        we = parse_time(work[6:11])

        for day in wanted_days:
            work_segments = segments(ws, we, delta)
            busy_segments = []
            rec = daymap.get(day)
            if rec:
                for ev in rec.get("events", []):
                    if ev.get("show_as") == "free":
                        continue
                    bs = parse_time(ev["start"])
                    be = parse_time(ev["end"])
                    for seg in segments(bs, be, delta):
                        busy_segments.append(seg)
            dayinfo[day] = (work_segments, busy_segments)

        people.append(dayinfo)

    if earliest:
        earliest_min = parse_time(earliest)
    else:
        earliest_min = 0

    if latest_end:
        latest_min = parse_time(latest_end)
    else:
        latest_min = 24 * 60

    starts = dict()

    for day in wanted_days:
        day_starts = []
        for start in range(0, 24 * 60, 15):
            end = start + minutes
            if start < earliest_min:
                continue
            if end > latest_min:
                continue
            if end > 24 * 60:
                continue

            ok = True
            for person in people:
                work_segments, busy_segments = person[day]

                in_work = False
                for seg_start, seg_end in work_segments:
                    if start >= seg_start and end <= seg_end:
                        in_work = True
                        break
                if not in_work:
                    ok = False
                    break

                for seg_start, seg_end in busy_segments:
                    if start < seg_end and end > seg_start:
                        ok = False
                        break
                if not ok:
                    break

            if ok:
                day_starts.append(time_text(start))

        if day_starts:
            starts[day] = day_starts

    return {"starts": starts}
