def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time_value(text):
        if text is None:
            return 0
        if isinstance(text, int):
            return text
        if isinstance(text, float):
            return int(text)
        text = str(text).strip()
        if text == "":
            return 0
        if ":" in text:
            parts = text.split(":")
            if len(parts) >= 2:
                return int(parts[0]) * 60 + int(parts[1])
        return int(text)

    def parse_offset(text):
        if text is None:
            return 0
        if isinstance(text, int):
            return text
        if isinstance(text, float):
            return int(text)
        text = str(text).strip()
        if text == "":
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
            text = text[1:]
        elif text[0] == "+":
            text = text[1:]
        text = text.strip()
        if text == "":
            return 0
        if ":" in text:
            parts = text.split(":")
            if len(parts) >= 2:
                return sign * (int(parts[0]) * 60 + int(parts[1]))
        return sign * int(text)

    def format_time(value):
        hour = value // 60
        minute = value - hour * 60
        if hour < 10:
            hour_text = "0" + str(hour)
        else:
            hour_text = str(hour)
        if minute < 10:
            minute_text = "0" + str(minute)
        else:
            minute_text = str(minute)
        return hour_text + ":" + minute_text

    def ceil_quarter(value):
        return ((value + 14) // 15) * 15

    def clean_interval(start, end):
        pieces = []
        if end <= start:
            a = max(0, start)
            b = 1440
            if a < b:
                pieces.append((a, b))
            a = 0
            b = min(1440, end)
            if a < b:
                pieces.append((a, b))
        else:
            a = max(0, start)
            b = min(1440, end)
            if a < b:
                pieces.append((a, b))
        return pieces

    def convert_interval(start_text, end_text, person_offset, user_offset, before_pad=0, after_pad=0):
        shift = user_offset - person_offset
        start = parse_time_value(start_text) + shift - before_pad
        end = parse_time_value(end_text) + shift + after_pad
        return clean_interval(start, end)

    def inside(start, end, intervals):
        for a, b in intervals:
            if start >= a and end <= b:
                return True
        return False

    def overlaps(start, end, intervals):
        for a, b in intervals:
            if start < b and end > a:
                return True
        return False

    def parse_minutes_value(value):
        if value is None:
            return 0
        if isinstance(value, int):
            return value
        if isinstance(value, float):
            return int(value)
        text = str(value).strip()
        if text == "":
            return 0
        if ":" in text:
            parts = text.split(":")
            if len(parts) >= 2:
                return int(parts[0]) * 60 + int(parts[1])
        return int(text)

    def get_padding_side(container, side):
        if not isinstance(container, dict):
            return -1

        if side == "before":
            direct_keys = [
                "before", "before_minutes", "before_padding", "before_buffer",
                "padding_before", "buffer_before", "transition_before",
                "lead", "pre"
            ]
        else:
            direct_keys = [
                "after", "after_minutes", "after_padding", "after_buffer",
                "padding_after", "buffer_after", "transition_after",
                "trail", "post"
            ]

        generic_keys = [
            "padding", "padding_minutes", "buffer", "buffers", "transition",
            "transition_minutes", "meeting_buffer", "event_padding", "busy_buffer",
            "busy_padding", "default_padding", "default_buffer", "buffer_minutes"
        ]

        nested_keys = [
            "rules", "calendar_rules", "scheduling", "schedule_rules",
            "availability_rules", "preferences"
        ]

        for key in direct_keys:
            if key in container:
                value = container[key]
                if isinstance(value, dict):
                    if side in value:
                        return parse_minutes_value(value[side])
                    if "minutes" in value:
                        return parse_minutes_value(value["minutes"])
                    if side == "before":
                        if "lead" in value:
                            return parse_minutes_value(value["lead"])
                        if "pre" in value:
                            return parse_minutes_value(value["pre"])
                    else:
                        if "trail" in value:
                            return parse_minutes_value(value["trail"])
                        if "post" in value:
                            return parse_minutes_value(value["post"])
                return parse_minutes_value(value)

        for key in generic_keys:
            if key in container:
                value = container[key]
                if isinstance(value, dict):
                    if side in value:
                        return parse_minutes_value(value[side])
                    if "minutes" in value:
                        return parse_minutes_value(value["minutes"])
                    if "before" in value and "after" in value:
                        return parse_minutes_value(value[side])
                return parse_minutes_value(value)

        for key in nested_keys:
            if key in container and isinstance(container[key], dict):
                value = get_padding_side(container[key], side)
                if value >= 0:
                    return value

        return -1

    result = {"starts": {}}

    earliest_minutes = 0
    if earliest != "":
        earliest_minutes = parse_time_value(earliest)

    latest_minutes = 1440
    if latest_end != "":
        latest_minutes = parse_time_value(latest_end)

    people = [""]
    for attendee in attendees:
        people.append(attendee)

    for day in days:
        user_data = api.read_calendar("", day)
        if not isinstance(user_data, dict):
            continue

        user_days = user_data.get("days", [])
        if not isinstance(user_days, list) or len(user_days) == 0:
            continue

        first_user_entry = None
        for entry in user_days:
            if isinstance(entry, dict):
                first_user_entry = entry
                break
        if first_user_entry is None:
            continue

        day_key = first_user_entry.get("day", day)
        if not isinstance(day_key, str) or day_key == "":
            day_key = day

        if "utc_offset" in user_data:
            user_offset = parse_offset(user_data.get("utc_offset", "+00:00"))
        else:
            user_offset = parse_offset(first_user_entry.get("utc_offset", "+00:00"))

        work_by_person = {}
        busy_by_person = {}
        complete = True

        for person in people:
            if person == "":
                data = user_data
            else:
                data = api.read_calendar(person, day)

            if not isinstance(data, dict):
                complete = False
                break

            entries = data.get("days", [])
            if not isinstance(entries, list) or len(entries) == 0:
                complete = False
                break

            if "utc_offset" in data:
                offset = parse_offset(data.get("utc_offset", "+00:00"))
            else:
                offset = parse_offset(entries[0].get("utc_offset", "+00:00"))

            default_before = get_padding_side(data, "before")
            if default_before < 0:
                for entry in entries:
                    if isinstance(entry, dict):
                        default_before = get_padding_side(entry, "before")
                        if default_before >= 0:
                            break
            if default_before < 0:
                default_before = 0

            default_after = get_padding_side(data, "after")
            if default_after < 0:
                for entry in entries:
                    if isinstance(entry, dict):
                        default_after = get_padding_side(entry, "after")
                        if default_after >= 0:
                            break
            if default_after < 0:
                default_after = 0

            work_hours = data.get("working_hours", "")
            if work_hours == "":
                for entry in entries:
                    if isinstance(entry, dict):
                        wh = entry.get("working_hours", "")
                        if wh != "":
                            work_hours = wh
                            break
            if work_hours == "":
                work_hours = "00:00-24:00"

            work_hours = str(work_hours).replace(" ", "")
            work_bits = work_hours.split("-")
            if len(work_bits) < 2:
                work_bits = ["00:00", "24:00"]

            work_parts = convert_interval(work_bits[0], work_bits[1], offset, user_offset)

            busy_parts = []
            for entry in entries:
                if not isinstance(entry, dict):
                    continue

                entry_before = get_padding_side(entry, "before")
                if entry_before < 0:
                    entry_before = default_before
                if entry_before < 0:
                    entry_before = 0

                entry_after = get_padding_side(entry, "after")
                if entry_after < 0:
                    entry_after = default_after
                if entry_after < 0:
                    entry_after = 0

                events = entry.get("events", [])
                if not isinstance(events, list):
                    continue

                for event in events:
                    if not isinstance(event, dict):
                        continue
                    if "start" not in event or "end" not in event:
                        continue
                    if event.get("show_as") == "free":
                        continue

                    before_pad = get_padding_side(event, "before")
                    if before_pad < 0:
                        before_pad = entry_before
                    if before_pad < 0:
                        before_pad = 0

                    after_pad = get_padding_side(event, "after")
                    if after_pad < 0:
                        after_pad = entry_after
                    if after_pad < 0:
                        after_pad = 0

                    parts = convert_interval(
                        event["start"],
                        event["end"],
                        offset,
                        user_offset,
                        before_pad,
                        after_pad
                    )
                    for part in parts:
                        busy_parts.append(part)

            work_by_person[person] = work_parts
            busy_by_person[person] = busy_parts

        if not complete:
            continue

        start_candidate = ceil_quarter(max(0, earliest_minutes))
        last_candidate = min(latest_minutes - minutes, 1440 - minutes)

        if last_candidate < start_candidate:
            continue

        day_starts = []
        for candidate in range(start_candidate, last_candidate + 1, 15):
            end_candidate = candidate + minutes
            ok = True

            for person in people:
                if not inside(candidate, end_candidate, work_by_person[person]):
                    ok = False
                    break
                if overlaps(candidate, end_candidate, busy_by_person[person]):
                    ok = False
                    break

            if ok:
                day_starts.append(format_time(candidate))

        if len(day_starts) > 0:
            result["starts"][day_key] = day_starts

    return result
