            return int(value)
        text = str(value).strip()
        if text == "":
            return -1
        try:
            if ":" in text:
                parts = text.split(":")
                if len(parts) >= 2:
                    return int(parts[0]) * 60 + int(parts[1])
            return int(text)
        except Exception:
            return -1

    def parse_padding_value(value, side):
        if isinstance(value, dict):
            if side in value:
                parsed = parse_minutes_value(value[side])
                if parsed >= 0:
                    return parsed
            if "minutes" in value:
                parsed = parse_minutes_value(value["minutes"])
                if parsed >= 0:
                    return parsed
            if side == "before":
                if "lead" in value:
                    parsed = parse_minutes_value(value["lead"])
                    if parsed >= 0:
                        return parsed
                if "pre" in value:
                    parsed = parse_minutes_value(value["pre"])
                    if parsed >= 0:
                        return parsed
            else:
                if "trail" in value:
                    parsed = parse_minutes_value(value["trail"])
                    if parsed >= 0:
                        return parsed
                if "post" in value:
                    parsed = parse_minutes_value(value["post"])
                    if parsed >= 0:
                        return parsed
            return -1

        parsed = parse_minutes_value(value)
        if parsed < 0:
            return -1
        return parsed

    def find_padding(container, side):
        if not isinstance(container, dict):
            return -1

        if side == "before":
            direct_keys = [
                "before", "before_minutes", "before_padding", "before_buffer",
                "padding_before", "buffer_before", "transition_before",
                "lead", "pre"
            ]
        else:
            direct_keys = [
                "after", "after_minutes", "after_padding", "after_buffer",
                "padding_after", "buffer_after", "transition_after",
                "trail", "post"
            ]

        generic_keys = [
            "padding", "padding_minutes", "buffer", "buffers", "transition",
            "transition_minutes", "meeting_buffer", "event_padding", "busy_buffer",
            "busy_padding", "default_padding", "default_buffer", "buffer_minutes"
        ]

        nested_keys = [
            "rules", "calendar_rules", "scheduling", "schedule_rules",
            "availability_rules", "preferences"
        ]

        for key in direct_keys:
            if key in container:
                value = container[key]
                parsed = parse_padding_value(value, side)
                if parsed >= 0:
                    return parsed
                if isinstance(value, dict):
                    parsed = find_padding(value, side)
                    if parsed >= 0:
                        return parsed

        for key in generic_keys:
            if key in container:
                value = container[key]
                parsed = parse_padding_value(value, side)
                if parsed >= 0:
                    return parsed
                if isinstance(value, dict):
                    parsed = find_padding(value, side)
                    if parsed >= 0:
                        return parsed

        for key in nested_keys:
            if key in container and isinstance(container[key], dict):
                parsed = find_padding(container[key], side)
                if parsed >= 0:
                    return parsed

        return -1

    def get_entries(data):
        if not isinstance(data, dict):
            return []
        entries = data.get("days", [])
        if isinstance(entries, list) and len(entries) > 0:
            return entries
        return [data]

    def get_offset(data, entries):
        if isinstance(data, dict) and "utc_offset" in data:
            return parse_offset(data.get("utc_offset", "+00:00"))
        for entry in entries:
            if isinstance(entry, dict) and "utc_offset" in entry:
                return parse_offset(entry.get("utc_offset", "+00:00"))
        return 0

    def get_work_hours(data, entries):
        if isinstance(data, dict) and "working_hours" in data:
            text = data.get("working_hours", "")
            if text != "":
                return str(text)
        for entry in entries:
            if isinstance(entry, dict):
                text = entry.get("working_hours", "")
                if text != "":
                    return str(text)
        return "00:00-24:00"

    def get_event_list(entry):
        for key in ["events", "busy", "meetings", "items"]:
            if key in entry and isinstance(entry[key], list):
                return entry[key]
        return []

    def convert_interval(start_text, end_text, person_offset, user_offset, before_pad=0, after_pad=0):
        shift = user_offset - person_offset
        start = parse_time(start_text) + shift - before_pad
        end = parse_time(end_text) + shift + after_pad
        return split_interval(start, end)

    result = {"starts": {}}

    earliest_minutes = 0
    if earliest != "":
        earliest_minutes = parse_time(earliest)

    latest_minutes = 1440
    if latest_end != "":
        latest_minutes = parse_time(latest_end)

    people = [""]
    for attendee in attendees:
        people.append(attendee)

    for day in days:
        user_data = api.read_calendar("", day)
        if not isinstance(user_data, dict):
            continue

        user_entries = get_entries(user_data)
        if len(user_entries) == 0:
            continue

        user_offset = get_offset(user_data, user_entries)

        first_user_entry = None
        for entry in user_entries:
            if isinstance(entry, dict):
                first_user_entry = entry
                break

        if first_user_entry is None:
            continue

        day_key = first_user_entry.get("day", day)
        if not isinstance(day_key, str) or day_key == "":
            day_key = day

        work_by_person = {}
        busy_by_person = {}
        complete = True

        for person in people:
            if person == "":
                data = user_data
            else:
                data = api.read_calendar(person, day)

            if not isinstance(data, dict):
                complete = False
                break

            entries = get_entries(data)
            if len(entries) == 0:
                complete = False
                break

            offset = get_offset(data, entries)

            default_before = find_padding(data, "before")
            if default_before < 0:
                default_before = 0

            default_after = find_padding(data, "after")
            if default_after < 0:
                default_after = 0

            work_hours = get_work_hours(data, entries)
            work_hours = str(work_hours).replace(" ", "")
            work_bits = work_hours.split("-")
            if len(work_bits) < 2:
                work_bits = ["00:00", "24:00"]

            work_parts = convert_interval(work_bits[0], work_bits[1], offset, user_offset)
            work_parts = merge_intervals(work_parts)

            busy_parts = []

            for entry in entries:
                if not isinstance(entry, dict):
                    continue

                entry_before = find_padding(entry, "before")
                if entry_before < 0:
                    entry_before = default_before

                entry_after = find_padding(entry, "after")
                if entry_after < 0:
                    entry_after = default_after

                event_list = get_event_list(entry)
                for event in event_list:
                    if not isinstance(event, dict):
                        continue
                    if "start" not in event or "end" not in event:
                        continue
                    if event.get("show_as") == "free":
                        continue

                    before_pad = find_padding(event, "before")
                    if before_pad < 0:
                        before_pad = entry_before
                    if before_pad < 0:
                        before_pad = 0

                    after_pad = find_padding(event, "after")
                    if after_pad < 0:
                        after_pad = entry_after
                    if after_pad < 0:
                        after_pad = 0

                    parts = convert_interval(
                        event["start"],
                        event["end"],
                        offset,
                        user_offset,
                        before_pad,
                        after_pad
                    )
                    for part in parts:
                        busy_parts.append(part)

            work_by_person[person] = work_parts
            busy_by_person[person] = merge_intervals(busy_parts)

        if not complete:
            continue

        start_candidate = ceil_quarter(max(0, earliest_minutes))
        last_candidate = min(latest_minutes - minutes, 1440 - minutes)

        if last_candidate < start_candidate:
            continue

        day_starts = []
        for candidate in range(start_candidate, last_candidate + 1, 15):
            end_candidate = candidate + minutes
            ok = True

            for person in people:
                if not inside(candidate, end_candidate, work_by_person[person]):
                    ok = False
                    break
                if overlaps(candidate, end_candidate, busy_by_person[person]):
                    ok = False
                    break

            if ok:
                day_starts.append(format_time(candidate))

        if len(day_starts) > 0:
            result["starts"][day_key] = day_starts

    return result
