def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(t):
        return int(t[:2]) * 60 + int(t[3:5])

    def to_time(m):
        h = m // 60
        n = m % 60
        return str(h).zfill(2) + ":" + str(n).zfill(2)

    def parse_offset(s):
        sign = 1
        if s and s[0] == "-":
            sign = -1
        h = int(s[1:3])
        n = int(s[4:6])
        return sign * (h * 60 + n)

    def ceil_quarter(m):
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def day_key(d):
        s = d.strip().lower()
        if len(s) >= 3:
            s = s[:3]
        if s in day_map:
            return s
        return ""

    def day_name(k):
        return name_map[k]

    def note_buffer(note):
        if not note:
            return 0
        parts = note.replace(".", " ").replace(",", " ").split()
        i = 0
        while i < len(parts):
            if parts[i].isdigit():
                return int(parts[i])
            i += 1
        return 0

    def pieces(start, end):
        out = []
        if end <= start:
            if start < 1440:
                s = start
                if s < 0:
                    s = 0
                if s < 1440:
                    out.append((s, 1440))
            if end > 0:
                e = end
                if e > 1440:
                    e = 1440
                if e > 0:
                    out.append((0, e))
        else:
            if end <= 0 or start >= 1440:
                return out
            s = start
            e = end
            if s < 0:
                s = 0
            if e > 1440:
                e = 1440
            if s < e:
                out.append((s, e))
        return out

    def merge(intervals):
        if len(intervals) == 0:
            return []
        intervals = sorted(intervals)
        merged = [list(intervals[0])]
        i = 1
        while i < len(intervals):
            s, e = intervals[i]
            if s <= merged[-1][1]:
                if e > merged[-1][1]:
                    merged[-1][1] = e
            else:
                merged.append([s, e])
            i += 1
        return [(x[0], x[1]) for x in merged]

    def subtract(free_intervals, busy_intervals):
        out = []
        for fs, fe in free_intervals:
            cur = fs
            for bs, be in busy_intervals:
                if be <= cur:
                    continue
                if bs >= fe:
                    break
                if bs > cur:
                    out.append((cur, bs if bs < fe else fe))
                if be > cur:
                    cur = be
                if cur >= fe:
                    break
            if cur < fe:
                out.append((cur, fe))
        return out

    def intersect(a, b):
        out = []
        i = 0
        j = 0
        while i < len(a) and j < len(b):
            s = a[i][0] if a[i][0] > b[j][0] else b[j][0]
            e = a[i][1] if a[i][1] < b[j][1] else b[j][1]
            if s < e:
                out.append((s, e))
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return out

    day_map = {
        "mon": "Monday",
        "tue": "Tuesday",
        "wed": "Wednesday",
        "thu": "Thursday",
        "fri": "Friday",
    }
    name_map = {
        "mon": "mon",
        "tue": "tue",
        "wed": "wed",
        "thu": "thu",
        "fri": "fri",
    }

    result = {"starts": {}}
    if len(days) == 0:
        return result

    seen = set()
    user_offset = None
    user_earliest = to_minutes(earliest) if earliest else 0
    user_latest = to_minutes(latest_end) if latest_end else 1440

    for original_day in days:
        k = day_key(original_day)
        if k == "" or k in seen:
            continue
        seen.add(k)

        calcs = []
        user_resp = api.read_calendar("", day_name(k))
        user_offset = parse_offset(user_resp["utc_offset"])
        calcs.append(("", user_resp, 0))

        for person in attendees:
            resp = api.read_calendar(person, day_name(k))
            person_offset = parse_offset(resp["utc_offset"])
            # correct conversion from the person's local clock to the user's clock
            delta = user_offset - person_offset
            calcs.append((person, resp, delta))

        common = None
        for person, resp, delta in calcs:
            note = resp.get("note", "")
            buffer = note_buffer(note)

            work = resp.get("working_hours", "09:00-17:00")
            work_start = to_minutes(work[:5]) + delta
            work_end = to_minutes(work[6:]) + delta
            work_intervals = pieces(work_start, work_end)

            day_events = []
            days_list = resp.get("days", [])
            idx = 0
            while idx < len(days_list):
                item = days_list[idx]
                if day_key(item.get("day", "")) == k:
                    day_events = item.get("events", [])
                    break
                idx += 1
            if len(days_list) == 1 and len(day_events) == 0:
                day_events = days_list[0].get("events", [])

            busy = []
            for ev in day_events:
                if ev.get("show_as") == "busy":
                    s = to_minutes(ev["start"]) + delta - buffer
                    e = to_minutes(ev["end"]) + delta + buffer
                    parts = pieces(s, e)
                    i = 0
                    while i < len(parts):
                        busy.append(parts[i])
                        i += 1

            busy = merge(busy)
            free = subtract(work_intervals, busy)

            if common is None:
                common = free
            else:
                common = intersect(common, free)

            if len(common) == 0:
                break

        starts = []
        if common is not None and len(common) > 0:
            for s, e in common:
                lo = s
                if lo < user_earliest:
                    lo = user_earliest
                hi = e
                if user_latest < hi:
                    hi = user_latest
                hi = hi - minutes
                if hi < lo:
                    continue
                cand = ceil_quarter(lo)
                while cand <= hi:
                    starts.append(to_time(cand))
                    cand += 15

        if len(starts) > 0:
            result["starts"][k] = starts

    return result
