def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def day_key(text):
        text = text.lower().strip()
        if len(text) >= 3:
            text = text[:3]
        return text

    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        hour = total // 60
        minute = total % 60
        if hour < 10:
            hour = "0" + str(hour)
        else:
            hour = str(hour)
        if minute < 10:
            minute = "0" + str(minute)
        else:
            minute = str(minute)
        return hour + ":" + minute

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        hour = int(text[1:3])
        minute = int(text[4:6])
        return sign * (hour * 60 + minute)

    def parse_hours(text):
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    def ceil_quarter(total):
        rem = total % 15
        if rem == 0:
            return total
        return total + (15 - rem)

    def floor_quarter(total):
        return total - (total % 15)

    def overlaps(a1, a2, b1, b2):
        return a1 < b2 and b1 < a2

    def build_calendar(data):
        offset = parse_offset(data.get("utc_offset", "+00:00"))
        work_start, work_end = parse_hours(data.get("working_hours", "09:00-17:00"))
        note = data.get("note", "").lower()
        buffer = 15 if "15 minute" in note else 0
        daymap = {}
        for item in data.get("days", []):
            dk = day_key(item.get("day", ""))
            intervals = []
            for event in item.get("events", []):
                if event.get("show_as", "busy") == "busy":
                    start = parse_time(event.get("start", "00:00")) - buffer
                    end = parse_time(event.get("end", "00:00")) + buffer
                    intervals.append((start, end))
            if dk in daymap:
                daymap[dk] = daymap[dk] + intervals
            else:
                daymap[dk] = intervals
        return {"offset": offset, "work_start": work_start, "work_end": work_end, "days": daymap}

    valid_days = set(["mon", "tue", "wed", "thu", "fri"])
    order = {"mon": 0, "tue": 1, "wed": 2, "thu": 3, "fri": 4}

    unique_days = []
    seen_days = set()
    for item in days:
        dk = day_key(item)
        if dk in valid_days and dk not in seen_days:
            seen_days.add(dk)
            unique_days.append(dk)
    unique_days = sorted(unique_days, key=order.get)

    user_calendar = build_calendar(api.read_calendar("", ""))
    user_offset = user_calendar["offset"]
    user_work_start = user_calendar["work_start"]
    user_work_end = user_calendar["work_end"]

    people = []
    seen_people = set()
    for name in attendees:
        if name and name not in seen_people:
            seen_people.add(name)
            people.append(name)

    calendars = {"": user_calendar}
    for name in people:
        calendars[name] = build_calendar(api.read_calendar(name, ""))

    earliest_min = user_work_start
    if earliest:
        earliest_min = parse_time(earliest)
        if earliest_min < user_work_start:
            earliest_min = user_work_start

    latest_limit = user_work_end
    if latest_end:
        latest_limit = parse_time(latest_end)
        if latest_limit > user_work_end:
            latest_limit = user_work_end

    result = {}
    first_start = ceil_quarter(earliest_min)
    last_start = floor_quarter(latest_limit - minutes)

    for day in unique_days:
        starts = []
        if first_start <= last_start:
            start_time = first_start
            while start_time <= last_start:
                end_time = start_time + minutes
                ok = True
                for name in calendars:
                    info = calendars[name]
                    delta = info["offset"] - user_offset
                    local_start = start_time + delta
                    local_end = end_time + delta
                    if local_start < 0 or local_end > 24 * 60:
                        ok = False
                        break
                    if local_start < info["work_start"] or local_end > info["work_end"]:
                        ok = False
                        break
                    for interval in info["days"].get(day, []):
                        if overlaps(local_start, local_end, interval[0], interval[1]):
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    starts.append(format_time(start_time))
                start_time += 15
        if starts:
            result[day] = starts

    return {"starts": result}
