        return str(hours).zfill(2) + ":" + str(mins).zfill(2)

    def parse_offset(value):
        sign = 1
        if value[0] == "-":
            sign = -1
        hours = int(value[1:3])
        mins = int(value[4:6])
        return sign * (hours * 60 + mins)

    def ceil_quarter(value):
        if value <= 0:
            return 0
        rem = value % 15
        if rem == 0:
            return value
        return value + (15 - rem)

    def floor_quarter(value):
        if value <= 0:
            return 0
        return value - (value % 15)

    def merge_intervals(intervals):
        if len(intervals) == 0:
            return []
        intervals = sorted(intervals)
        merged = [list(intervals[0])]
        for start, end in intervals[1:]:
            last = merged[-1]
            if start <= last[1]:
                if end > last[1]:
                    last[1] = end
            else:
                merged.append([start, end])
        return merged

    starts = {}
    earliest_bound = parse_time(earliest) if earliest != "" else 0
    latest_bound = parse_time(latest_end) if latest_end != "" else 24 * 60

    if earliest_bound < 0:
        earliest_bound = 0
    if latest_bound > 24 * 60:
        latest_bound = 24 * 60

    for day in days:
        user_data = api.read_calendar("", day)
        user_offset = parse_offset(user_data["utc_offset"])
        user_hours = user_data["working_hours"]
        user_work_start = parse_time(user_hours[0:5])
        user_work_end = parse_time(user_hours[6:11])

        start_limit = user_work_start
        end_limit = user_work_end
        blocked = []

        user_days = user_data.get("days", [])
        user_events = []
        if len(user_days) > 0:
            user_events = user_days[0].get("events", [])
        for event in user_events:
            if event.get("show_as") == "busy":
                blocked.append((parse_time(event["start"]), parse_time(event["end"])))

        for person in attendees:
            data = api.read_calendar(person, day)
            person_offset = parse_offset(data["utc_offset"])
            delta = person_offset - user_offset

            hours = data["working_hours"]
            work_start = parse_time(hours[0:5]) - delta
            work_end = parse_time(hours[6:11]) - delta

            if work_start > start_limit:
                start_limit = work_start
            if work_end < end_limit:
                end_limit = work_end

            note = data.get("note", "")
            buffer = 15 if "15 minutes" in note else 0

            person_days = data.get("days", [])
            person_events = []
            if len(person_days) > 0:
                person_events = person_days[0].get("events", [])
            for event in person_events:
                if event.get("show_as") == "busy":
                    start = parse_time(event["start"]) - delta - buffer
                    end = parse_time(event["end"]) - delta + buffer
                    blocked.append((start, end))

        if earliest_bound > start_limit:
            start_limit = earliest_bound
        if latest_bound < end_limit:
            end_limit = latest_bound

        if start_limit < 0:
            start_limit = 0
        if end_limit > 24 * 60:
            end_limit = 24 * 60

        last_start = end_limit - minutes
        if last_start < start_limit:
            continue

        first_candidate = ceil_quarter(start_limit)
        last_candidate = floor_quarter(last_start)
        if first_candidate > last_candidate:
            continue

        merged_blocked = merge_intervals(blocked)
        day_starts = []

        candidate = first_candidate
        while candidate <= last_candidate:
            candidate_end = candidate + minutes
            conflict = False
            for block_start, block_end in merged_blocked:
                if candidate < block_end and candidate_end > block_start:
                    conflict = True
                    break
            if not conflict:
                day_starts.append(format_time(candidate))
            candidate += 15

        if len(day_starts) > 0:
            starts[day] = day_starts

    return {"starts": starts}
