def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(value):
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            if 0 <= value <= 1440:
                return value
            return None
        if isinstance(value, float):
            value = int(round(value))
            if 0 <= value <= 1440:
                return value
            return None
        if isinstance(value, str):
            text = value.strip()
            if text == "":
                return None
            parts = text.split(":")
            if len(parts) != 2:
                return None
            try:
                hour = int(parts[0].strip())
                minute = int(parts[1].strip())
            except Exception:
                return None
            if 0 <= hour <= 24 and 0 <= minute < 60 and not (hour == 24 and minute != 0):
                return hour * 60 + minute
        return None

    def format_time(total):
        hour, minute = divmod(total, 60)
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def round_up_quarter(total):
        remainder = total % 15
        if remainder == 0:
            return total
        return total + (15 - remainder)

    def extract_times(text):
        times = []
        i = 0
        while i < len(text):
            if text[i].isdigit():
                j = i
                while j < len(text) and text[j].isdigit():
                    j += 1
                if j < len(text) and text[j] == ":":
                    k = j + 1
                    while k < len(text) and text[k].isdigit():
                        k += 1
                    if k > j + 1:
                        try:
                            hour = int(text[i:j])
                            minute = int(text[j + 1:k])
                        except Exception:
                            hour = -1
                            minute = -1
                        if 0 <= hour <= 24 and 0 <= minute < 60 and not (hour == 24 and minute != 0):
                            times.append(hour * 60 + minute)
                        i = k
                        continue
            i += 1
        return times

    def collect_intervals(item, intervals):
        if item is None:
            return

        if isinstance(item, dict):
            low = {}
            for key in item:
                low[str(key).lower()] = key

            start_key = None
            end_key = None

            for name in ["start", "begin", "from", "starttime", "start_time", "begins"]:
                if name in low:
                    start_key = low[name]
                    break

            for name in ["end", "finish", "to", "until", "endtime", "end_time", "stop"]:
                if name in low:
                    end_key = low[name]
                    break

            if start_key is not None and end_key is not None:
                start_value = parse_time(item[start_key])
                end_value = parse_time(item[end_key])
                if start_value is not None and end_value is not None:
                    intervals.append((start_value, end_value))
                    return

            for value in item.values():
                collect_intervals(value, intervals)
            return

        if isinstance(item, tuple) or isinstance(item, list):
            if len(item) == 2:
                start_value = parse_time(item[0])
                end_value = parse_time(item[1])
                if start_value is not None and end_value is not None:
                    intervals.append((start_value, end_value))
                    return
            for value in item:
                collect_intervals(value, intervals)
            return

        if isinstance(item, str):
            times = extract_times(item)
            i = 0
            while i + 1 < len(times):
                intervals.append((times[i], times[i + 1]))
                i += 2
            return

    people = []
    seen = set()
    for name in [""] + attendees:
        if name not in seen:
            seen.add(name)
            people.append(name)

    start_bound = parse_time(earliest)
    if start_bound is None:
        start_bound = 0

    end_bound = parse_time(latest_end)
    if end_bound is None:
        end_bound = 1440

    if start_bound < 0:
        start_bound = 0
    if end_bound < 0:
        end_bound = 0
    if start_bound > 1440:
        start_bound = 1440
    if end_bound > 1440:
        end_bound = 1440

    results = {}

    for day in days:
        intervals = []
        for person in people:
            collect_intervals(api.read_calendar(person, day), intervals)

        merged = []
        for start_value, end_value in sorted(intervals):
            if start_value < 0:
                start_value = 0
            if end_value < 0:
                end_value = 0
            if start_value > 1440:
                start_value = 1440
            if end_value > 1440:
                end_value = 1440
            if end_value <= start_value:
                continue

            if len(merged) == 0 or start_value > merged[-1][1]:
                merged.append([start_value, end_value])
            else:
                if end_value > merged[-1][1]:
                    merged[-1][1] = end_value

        starts = []
        candidate = round_up_quarter(start_bound)
        last_candidate = end_bound - minutes

        while candidate <= last_candidate and candidate < 1440:
            finish = candidate + minutes
            free = True
            for busy_start, busy_end in merged:
                if busy_end <= candidate:
                    continue
                if busy_start >= finish:
                    break
                free = False
                break
            if free:
                starts.append(format_time(candidate))
            candidate += 15

        if len(starts) > 0:
            results[day] = starts

    return {"starts": results}
