    def parse_time(text):
        if not text:
            return 0
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        h, m = divmod(total, 60)
        return ("0" if h < 10 else "") + str(h) + ":" + ("0" if m < 10 else "") + str(m)

    def parse_offset(text):
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        body = text[1:] if text[0] == "-" or text[0] == "+" else text
        parts = body.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def ceil_quarter(total):
        q, r = divmod(total, 15)
        if r == 0:
            return q * 15
        return (q + 1) * 15

    def parse_working_hours(text):
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    def pick_day_info(data, day):
        items = data.get("days", [])
        want = day.lower()[:3]
        for item in items:
            if str(item.get("day", "")).lower()[:3] == want:
                return item
        if items:
            return items[0]
        return {}

    def parse_buffer(note):
        if not note:
            return 0
        text = note.replace("-", " ").replace(",", " ").replace(".", " ")
        words = text.split()
        for i in range(len(words) - 1):
            if words[i].isdigit() and "minute" in words[i + 1].lower():
                return int(words[i])
        return 0

    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = []
        for start, end in intervals:
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            elif end > merged[-1][1]:
                merged[-1][1] = end
        return merged

    if not days:
        return {"starts": []}

    start_floor = 0
    if earliest:
        start_floor = ceil_quarter(parse_time(earliest))

    start_cap = 24 * 60 - 15
    if latest_end:
        start_cap = min(start_cap, parse_time(latest_end) - minutes)
    start_cap = min(start_cap, 24 * 60 - minutes)

    if start_cap < start_floor:
        return {"starts": []}

    common = None

    for day in days:
        people = []
        user_data = api.read_calendar("", day)
        user_day = pick_day_info(user_data, day)
        user_offset = parse_offset(user_data.get("utc_offset", ""))

        all_people = [("", user_data, user_day)] + [(name, api.read_calendar(name, day), None) for name in attendees]

        day_starts = set()

        for person, data, preset_day in all_people:
            day_info = preset_day if preset_day is not None else pick_day_info(data, day)
            offset = parse_offset(data.get("utc_offset", ""))
            delta = user_offset - offset

            work_start, work_end = parse_working_hours(data.get("working_hours", "00:00-24:00"))
            work_start += delta
            work_end += delta

            buffer = parse_buffer(data.get("note", ""))
            busy = []
            events = day_info.get("events", [])
            for event in events:
                if str(event.get("show_as", "busy")).lower() == "free":
                    continue
                a = parse_time(event.get("start", "00:00")) - buffer + delta
                b = parse_time(event.get("end", "00:00")) + buffer + delta
                busy.append((a, b))

            busy = merge_intervals(busy)

            s = start_floor
            while s <= start_cap:
                e = s + minutes
                if e > 24 * 60:
                    s += 15
                    continue

                ok = True
                if s < work_start or e > work_end:
                    ok = False
                else:
                    for a, b in busy:
                        if s < b and e > a:
                            ok = False
                            break

                if ok:
                    day_starts.add(format_time(s))

                s += 15

        if common is None:
            common = day_starts
        else:
            common = common.intersection(day_starts)

        if not common:
            return {"starts": []}

    return {"starts": sorted(common)}
