            return parts
        if end > 1440:
            parts.append((start, 1440))
            parts.append((0, end - 1440))
            return parts
        if end > start:
            parts.append((start, end))
        return parts

    def getbuffers(item, mode, skip_events):
        before = 0
        after = 0
        if isinstance(item, dict):
            for key, val in item.items():
                name = str(key).lower()
                nextmode = mode
                if "buffer" in name or "padding" in name:
                    nextmode = "both"
                elif "before" in name or name.startswith("pre") or "lead" in name:
                    nextmode = "before"
                elif "after" in name or name.startswith("post") or "lag" in name:
                    nextmode = "after"

                if skip_events and name == "events":
                    continue

                if isinstance(val, bool):
                    continue
                if isinstance(val, (int, float)):
                    amount = int(val)
                    if nextmode == "both":
                        before += amount
                        after += amount
                    elif nextmode == "before":
                        before += amount
                    elif nextmode == "after":
                        after += amount
                elif isinstance(val, str):
                    txt = val.strip()
                    if txt != "" and txt.lstrip("+-").isdigit():
                        amount = int(txt)
                        if nextmode == "both":
                            before += amount
                            after += amount
                        elif nextmode == "before":
                            before += amount
                        elif nextmode == "after":
                            after += amount
                elif isinstance(val, dict) or isinstance(val, list) or isinstance(val, tuple):
                    b, a = getbuffers(val, nextmode, skip_events)
                    before += b
                    after += a
        elif isinstance(item, list) or isinstance(item, tuple):
            for val in item:
                b, a = getbuffers(val, mode, skip_events)
                before += b
                after += a
        return before, after

    def fitsin(parts, start, end):
        for partstart, partend in parts:
            if start >= partstart and end <= partend:
                return True
        return False

    def overlaps(parts, start, end):
        for partstart, partend in parts:
            if start < partend and end > partstart:
                return True
        return False

    def parsecalendar(cal, personoffset, useroffset):
        defaultbefore, defaultafter = getbuffers(cal, "", True)

        workvalue = cal.get("working_hours", "")
        workstarttext = ""
        workendtext = ""

        if isinstance(workvalue, str):
            workparts = workvalue.split("-")
            if len(workparts) >= 2:
                workstarttext = workparts[0].strip()
                workendtext = workparts[1].strip()
        elif isinstance(workvalue, dict):
            if "start" in workvalue and "end" in workvalue:
                workstarttext = str(workvalue["start"]).strip()
                workendtext = str(workvalue["end"]).strip()
        elif isinstance(workvalue, list) or isinstance(workvalue, tuple):
            if len(workvalue) >= 2:
                workstarttext = str(workvalue[0]).strip()
                workendtext = str(workvalue[1]).strip()

        if workstarttext == "" or workendtext == "":
            return None

        workstart = shift(timetominutes(workstarttext), personoffset, useroffset)
        workend = shift(timetominutes(workendtext), personoffset, useroffset)
        worklen = intervalduration(timetominutes(workstarttext), timetominutes(workendtext))
        workparts = intervalparts(workstart, workstart + worklen)
        if len(workparts) == 0:
            return None

        daysvalue = cal.get("days", [])
        if not isinstance(daysvalue, list) or len(daysvalue) == 0:
            return None

        dayvalue = daysvalue[0]
        events = dayvalue.get("events", [])
        if not isinstance(events, list):
            return None

        busy = []
        for ev in events:
            state = str(ev.get("show_as", "busy")).lower()
            if state == "free" or state == "available":
                continue
            if isinstance(ev.get("busy"), bool) and ev.get("busy") is False:
                continue

            before, after = getbuffers(ev, "", False)
            before += defaultbefore
            after += defaultafter

            evstarttext = str(ev.get("start", "")).strip()
            evendtext = str(ev.get("end", "")).strip()
            if evstarttext == "" or evendtext == "":
                continue

            evstartlocal = timetominutes(evstarttext)
            evendlocal = timetominutes(evendtext)
            evstart = shift(evstartlocal - before, personoffset, useroffset)
            evend = shift(evendlocal + after, personoffset, useroffset)
            evlen = intervalduration(evstartlocal - before, evendlocal + after)
            parts = intervalparts(evstart, evstart + evlen)
            for part in parts:
                busy.append(part)

        return {"startparts": workparts, "busy": busy}

    if minutes < 0 or len(days) == 0:
        return {"starts": []}

    earliest = str(earliest).strip()
    latest_end = str(latest_end).strip()

    dayinfos = []
    for day in days:
        usercal = api.read_calendar("", day)
        useroffset = offsettominutes(usercal.get("utc_offset", ""))
        userinfo = parsecalendar(usercal, useroffset, useroffset)
        if userinfo is None:
            return {"starts": []}

        infos = [userinfo]
        for person in attendees:
            cal = api.read_calendar(person, day)
            personoffset = offsettominutes(cal.get("utc_offset", ""))
            info = parsecalendar(cal, personoffset, useroffset)
            if info is None:
                return {"starts": []}
            infos.append(info)
        dayinfos.append(infos)

    lower = 0
    if earliest != "":
        lower = timetominutes(earliest)
    if lower < 0:
        lower = 0

    upper = 1440 - minutes
    if latest_end != "":
        upper = timetominutes(latest_end) - minutes
    if upper > 1440 - minutes:
        upper = 1440 - minutes

    if upper < lower:
        return {"starts": []}

    start = ((lower + 14) // 15) * 15
    last = (upper // 15) * 15
    starts = []

    while start <= last:
        end = start + minutes
        ok = True

        for infos in dayinfos:
            for info in infos:
                if not fitsin(info["startparts"], start, end):
                    ok = False
                    break
                if overlaps(info["busy"], start, end):
                    ok = False
                    break
            if not ok:
                break

        if ok:
            starts.append(minutestotime(start))

        start += 15

    return {"starts": starts}
