def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        txt = str(text).strip()
        if txt == "":
            return 0
        if ":" in txt:
            parts = txt.split(":")
            if len(parts) >= 2:
                return int(parts[0]) * 60 + int(parts[1])
        if txt.isdigit():
            if len(txt) <= 2:
                return int(txt) * 60
            if len(txt) == 3:
                return int(txt[0]) * 60 + int(txt[1:])
            if len(txt) == 4:
                return int(txt[:2]) * 60 + int(txt[2:])
            return int(txt)
        return 0

    def to_time(value):
        value = int(value)
        hour = value // 60
        minute = value % 60
        htext = str(hour)
        mtext = str(minute)
        if hour < 10:
            htext = "0" + htext
        if minute < 10:
            mtext = "0" + mtext
        return htext + ":" + mtext

    def parse_offset(text):
        txt = str(text).strip()
        if txt == "":
            return 0
        low = txt.lower()
        if low.startswith("utc") or low.startswith("gmt"):
            txt = txt[3:].strip()
        if txt == "z" or txt == "Z":
            return 0
        sign = 1
        if txt[0] == "-":
            sign = -1
            txt = txt[1:].strip()
        elif txt[0] == "+":
            txt = txt[1:].strip()
        if ":" in txt:
            parts = txt.split(":")
            if len(parts) >= 2:
                return sign * (int(parts[0]) * 60 + int(parts[1]))
        if txt.isdigit():
            if len(txt) <= 2:
                return sign * int(txt) * 60
            if len(txt) == 3:
                return sign * (int(txt[0]) * 60 + int(txt[1:]))
            if len(txt) == 4:
                return sign * (int(txt[:2]) * 60 + int(txt[2:]))
            return sign * int(txt)
        return 0

    def parse_duration(text):
        txt = str(text).strip().lower()
        if txt == "":
            return 0
        sign = 1
        if txt[0] == "-":
            sign = -1
            txt = txt[1:].strip()
        elif txt[0] == "+":
            txt = txt[1:].strip()
        if ":" in txt:
            parts = txt.split(":")
            if len(parts) >= 2:
                return sign * (int(parts[0]) * 60 + int(parts[1]))
        if txt.endswith("m") and txt[:-1].isdigit():
            return sign * int(txt[:-1])
        if txt.endswith("h") and txt[:-1].isdigit():
            return sign * int(txt[:-1]) * 60
        if txt.isdigit():
            return sign * int(txt)
        return 0

    def interval_duration(start, end):
        if end < start:
            return 1440 - start + end
        return end - start

    def interval_parts(start, end):
        parts = []
        if end <= 0 or start >= 1440:
            return parts
        if start < 0:
            if end > 1440:
                parts.append((0, 1440))
            elif end > 0:
                parts.append((0, end))
            return parts
        if end > 1440:
            parts.append((start, 1440))
            parts.append((0, end - 1440))
            return parts
        if end > start:
            parts.append((start, end))
        return parts

    def interval_fits(parts, start, end):
        for partstart, partend in parts:
            if start >= partstart and end <= partend:
                return True
        return False

    def intervals_overlap(parts, start, end):
        for partstart, partend in parts:
            if start < partend and end > partstart:
                return True
        return False

    def pick_value(obj, names):
        for name in names:
            if name in obj:
                val = obj.get(name, "")
                if val is not None:
                    return val
        return ""

    def get_pair(item):
        if isinstance(item, dict):
            s = pick_value(item, ["start", "begin", "from", "start_time", "starttime", "start_at"])
            e = pick_value(item, ["end", "finish", "to", "end_time", "endtime", "end_at"])
            if str(s).strip() != "" and str(e).strip() != "":
                return str(s).strip(), str(e).strip()
            return None
        if isinstance(item, list) or isinstance(item, tuple):
            if len(item) == 2 and not isinstance(item[0], dict) and not isinstance(item[1], dict) \
               and not isinstance(item[0], list) and not isinstance(item[1], list) \
               and not isinstance(item[0], tuple) and not isinstance(item[1], tuple):
                s = str(item[0]).strip()
                e = str(item[1]).strip()
                if s != "" and e != "":
                    return s, e
            return None
        if isinstance(item, str):
            txt = item.strip().replace(";", ",")
            if "," in txt:
                return None
            parts = txt.split("-")
            if len(parts) >= 2:
                s = parts[0].strip()
                e = parts[1].strip()
                if s != "" and e != "":
                    return s, e
        return None

    def collect_ranges(value):
        ranges = []
        if isinstance(value, str):
            txt = value.strip().replace(";", ",")
            pieces = txt.split(",")
            for piece in pieces:
                pair = get_pair(piece)
                if pair is not None:
                    ranges.append(pair)
        elif isinstance(value, dict):
            pair = get_pair(value)
            if pair is not None:
                ranges.append(pair)
            else:
                for sub in value.values():
                    subranges = collect_ranges(sub)
                    for pair in subranges:
                        ranges.append(pair)
        elif isinstance(value, list) or isinstance(value, tuple):
            pair = get_pair(value)
            if pair is not None:
                ranges.append(pair)
            else:
                for item in value:
                    subranges = collect_ranges(item)
                    for pair in subranges:
                        ranges.append(pair)
        return ranges

    def collect_buffers(item, mode, skip_events):
        before = 0
        after = 0
        if isinstance(item, dict):
            for key, val in item.items():
                name = str(key).lower().strip()
                if skip_events and (name == "events" or name == "busy" or name == "meetings" or name == "appointments"):
                    continue

                nextmode = mode
                if "before" in name or name.startswith("pre") or "lead" in name:
                    nextmode = "before"
                elif "after" in name or name.startswith("post") or "lag" in name:
                    nextmode = "after"
                elif "buffer" in name or "padding" in name or "gap" in name or "spacing" in name or "transition" in name:
                    nextmode = "both"

                if isinstance(val, bool):
                    continue

                amount = 0
                if isinstance(val, int):
                    amount = val
                elif isinstance(val, float):
                    amount = int(val)
                elif isinstance(val, str):
                    amount = parse_duration(val)

                if amount != 0:
                    if nextmode == "before":
                        before += amount
                    elif nextmode == "after":
                        after += amount
                    elif nextmode == "both":
                        before += amount
                        after += amount

                if isinstance(val, dict) or isinstance(val, list) or isinstance(val, tuple):
                    b, a = collect_buffers(val, nextmode, skip_events)
                    before += b
                    after += a
        elif isinstance(item, list) or isinstance(item, tuple):
            for val in item:
                b, a = collect_buffers(val, mode, skip_events)
                before += b
                after += a
        return before, after

    def pick_workvalue(container):
        if isinstance(container, dict):
            for key in ["working_hours", "work_hours"]:
                if key in container:
                    val = container.get(key, "")
                    if val is not None:
                        return val
        return ""

    def pick_events(container):
        if isinstance(container, dict):
            for key in ["events", "busy", "meetings", "appointments"]:
                val = container.get(key, None)
                if isinstance(val, list) and len(val) > 0:
                    return val
        return None

    def parsecalendar(cal, personoffset, useroffset):
        defaultbefore, defaultafter = collect_buffers(cal, "", True)

        daysvalue = []
        if isinstance(cal, dict):
            daysvalue = cal.get("days", [])
        dayrec = None
        if isinstance(daysvalue, list) and len(daysvalue) > 0 and isinstance(daysvalue[0], dict):
            dayrec = daysvalue[0]

        workvalue = ""
        workranges = []
        if dayrec is not None:
            workvalue = pick_workvalue(dayrec)
            workranges = collect_ranges(workvalue)
        if len(workranges) == 0:
            workvalue = pick_workvalue(cal)
            workranges = collect_ranges(workvalue)
        if len(workranges) == 0:
            return None

        workparts = []
        for pair in workranges:
            workstarttext = pair[0]
            workendtext = pair[1]
            localstart = to_minutes(workstarttext)
            localend = to_minutes(workendtext)
            shiftedstart = localstart + useroffset - personoffset
            duration = interval_duration(localstart, localend)
            parts = interval_parts(shiftedstart, shiftedstart + duration)
            for part in parts:
                workparts.append(part)

        if len(workparts) == 0:
            return None

        eventsvalue = None
        if dayrec is not None:
            eventsvalue = pick_events(dayrec)
        if eventsvalue is None:
            eventsvalue = pick_events(cal)
        if eventsvalue is None:
            eventsvalue = []
        if not isinstance(eventsvalue, list):
            return None

        busy = []
        for ev in eventsvalue:
            if not isinstance(ev, dict):
                continue

            state = ""
            for key in ["show_as", "status", "availability"]:
                if key in ev:
                    state = str(ev.get(key, "")).lower().strip()
                    break
            if state == "free" or state == "available" or state == "open":
                continue

            busyflag = ev.get("busy", None)
            if isinstance(busyflag, bool) and busyflag is False:
                continue
            if isinstance(busyflag, str) and busyflag.strip().lower() in ["false", "no", "0", "free", "available"]:
                continue
            if isinstance(busyflag, int) and busyflag == 0:
                continue

            before, after = collect_buffers(ev, "", False)
            before += defaultbefore
            after += defaultafter

            times = get_pair(ev)
            if times is None:
                continue

            evstartlocal = to_minutes(times[0])
            evendlocal = to_minutes(times[1])
            evstart = evstartlocal + useroffset - personoffset - before
            evend = evendlocal + useroffset - personoffset + after
            evlen = interval_duration(evstartlocal - before, evendlocal + after)
            parts = interval_parts(evstart, evstart + evlen)
            for part in parts:
                busy.append(part)

        return {"workparts": workparts, "busy": busy}

    try:
        minutes = int(minutes)
    except Exception:
        return {"starts": []}

    if minutes < 0 or len(days) == 0:
        return {"starts": []}

    earliest = str(earliest).strip()
    latest_end = str(latest_end).strip()

    lower = 0
    if earliest != "":
        lower = to_minutes(earliest)
    if lower < 0:
        lower = 0

    upper = 1440 - minutes
    if latest_end != "":
        upper = to_minutes(latest_end) - minutes
    if upper > 1439:
        upper = 1439
    if upper < 0:
        return {"starts": []}

    start = lower
    rem = start % 15
    if rem != 0:
        start += 15 - rem
    last = upper - (upper % 15)
    if last > 1435:
        last = 1435

    if start > last:
        return {"starts": []}

    common = None

    for day in days:
        usercal = api.read_calendar("", day)
        if not isinstance(usercal, dict):
            return {"starts": []}
        useroffset = parse_offset(usercal.get("utc_offset", ""))
        userinfo = parsecalendar(usercal, useroffset, useroffset)
        if userinfo is None:
            return {"starts": []}

        infos = [userinfo]
        for person in attendees:
            cal = api.read_calendar(person, day)
            if not isinstance(cal, dict):
                return {"starts": []}
            personoffset = parse_offset(cal.get("utc_offset", ""))
            info = parsecalendar(cal, personoffset, useroffset)
            if info is None:
                return {"starts": []}
            infos.append(info)

        daystarts = []
        candidate = start
        while candidate <= last:
            end = candidate + minutes
            ok = True
            for info in infos:
                if not interval_fits(info["workparts"], candidate, end):
                    ok = False
                    break
                if intervals_overlap(info["busy"], candidate, end):
                    ok = False
                    break
            if ok:
                daystarts.append(to_time(candidate))
            candidate += 15

        if common is None:
            common = daystarts
        else:
            dayset = set(daystarts)
            newcommon = []
            for t in common:
                if t in dayset:
                    newcommon.append(t)
            common = newcommon

        if len(common) == 0:
            return {"starts": []}

    if common is None:
        common = []

    return {"starts": common}
