def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def day_aliases(day):
        d = str(day).strip().lower()
        if d.startswith("mon"):
            return ["mon", "monday"]
        if d.startswith("tue"):
            return ["tue", "tues", "tuesday"]
        if d.startswith("wed"):
            return ["wed", "wednesday"]
        if d.startswith("thu"):
            return ["thu", "thur", "thurs", "thursday"]
        if d.startswith("fri"):
            return ["fri", "friday"]
        return [d]

    def parse_offset(text):
        if isinstance(text, bool):
            return 0
        if isinstance(text, int):
            n = int(text)
            if -24 <= n <= 24:
                return n * 60
            return n
        if isinstance(text, float):
            if int(text) == text:
                return parse_offset(int(text))
            return 0

        txt = str(text).strip()
        if txt == "":
            return 0
        low = txt.lower()
        if low.startswith("utc"):
            txt = txt[3:].strip()
        elif low.startswith("gmt"):
            txt = txt[3:].strip()
        txt = txt.strip()
        if txt == "":
            return 0
        if txt == "z" or txt == "Z":
            return 0

        sign = 1
        if txt[0] == "-":
            sign = -1
            txt = txt[1:].strip()
        elif txt[0] == "+":
            txt = txt[1:].strip()

        if txt == "":
            return 0

        if ":" in txt:
            parts = txt.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                return sign * (int(parts[0]) * 60 + int(parts[1]))

        if txt.isdigit():
            if len(txt) <= 2:
                return sign * int(txt) * 60
            if len(txt) == 3:
                return sign * (int(txt[0]) * 60 + int(txt[1:]))
            if len(txt) == 4:
                return sign * (int(txt[:2]) * 60 + int(txt[2:]))
            return sign * int(txt)

        return 0

    def parse_duration(text):
        if isinstance(text, bool):
            return 0
        if isinstance(text, int):
            return int(text)
        if isinstance(text, float):
            return int(text)

        txt = str(text).strip().lower()
        if txt == "":
            return 0

        sign = 1
        if txt[0] == "-":
            sign = -1
            txt = txt[1:].strip()
        elif txt[0] == "+":
            txt = txt[1:].strip()

        if txt == "":
            return 0

        if ":" in txt:
            parts = txt.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                return sign * (int(parts[0]) * 60 + int(parts[1]))

        if "h" in txt:
            pos = txt.find("h")
            hs = txt[:pos].strip()
            rest = txt[pos + 1:].strip()
            h = 0
            m = 0
            if hs.isdigit():
                h = int(hs)
            if rest.endswith("m") and rest[:-1].strip().isdigit():
                m = int(rest[:-1].strip())
            elif rest.isdigit():
                m = int(rest)
            return sign * (h * 60 + m)

        if txt.endswith("m") and txt[:-1].strip().isdigit():
            return sign * int(txt[:-1].strip())

        if txt.isdigit():
            return sign * int(txt)

        return 0

    def to_time(value):
        value = int(value)
        if value < 0:
            value = 0
        if value > 1440:
            value = 1440
        hour = value // 60
        minute = value % 60
        if hour == 24 and minute == 0:
            return "24:00"
        htext = str(hour)
        mtext = str(minute)
        if hour < 10:
            htext = "0" + htext
        if minute < 10:
            mtext = "0" + mtext
        return htext + ":" + mtext

    def parse_time_token(token, allow_plain):
        t = str(token).strip().lower()
        if t == "":
            return None
        while len(t) > 0 and (t[-1] == "." or t[-1] == "," or t[-1] == ";" or t[-1] == ":"):
            t = t[:-1].strip()
        if t == "":
            return None

        if t == "noon":
            return 12 * 60
        if t == "midnight":
            return 0

        ampm = ""
        if t.endswith("am") or t.endswith("pm"):
            ampm = t[-2:]
            t = t[:-2].strip()

        if t == "":
            return None

        if ":" in t:
            parts = t.split(":")
            if len(parts) >= 2 and parts[0].strip().isdigit() and parts[1].strip().isdigit():
                h = int(parts[0])
                m = int(parts[1])
                if ampm == "am":
                    if h == 12:
                        h = 0
                elif ampm == "pm":
                    if h < 12:
                        h += 12
                if h == 24 and m == 0:
                    return 1440
                if 0 <= h < 24 and 0 <= m < 60:
                    return h * 60 + m
            return None

        if not t.isdigit():
            return None

        if ampm != "":
            h = int(t)
            if h == 12:
                h = 0
            if ampm == "pm":
                h += 12
            if h == 24:
                return 1440
            if 0 <= h < 24:
                return h * 60
            return None

        if len(t) <= 2:
            h = int(t)
            if h == 24:
                return 1440
            if 0 <= h < 24:
                return h * 60
            return None

        if allow_plain:
            if len(t) == 3:
                h = int(t[0])
                m = int(t[1:])
                if h == 24 and m == 0:
                    return 1440
                if h < 24 and m < 60:
                    return h * 60 + m
            if len(t) == 4:
                h = int(t[:2])
                m = int(t[2:])
                if h == 24 and m == 0:
                    return 1440
                if h < 24 and m < 60:
                    return h * 60 + m
        return None

    def extract_time_points(text):
        s = str(text).strip()
        if s == "":
            return []
        s = s.replace("T", " ")
        for ch in [",", ";", "|", "(", ")", "[", "]", "{", "}", "<", ">", "\\", "/", "\n", "\r", "\t", "-", "–", "—", "~", "="]:
            s = s.replace(ch, " ")
        tokens = s.split()
        explicit = False
        digitcount = 0
        for tok in tokens:
            low = tok.lower()
            if ":" in low or low.endswith("am") or low.endswith("pm") or low == "noon" or low == "midnight":
                explicit = True
            if tok.isdigit():
                digitcount += 1
        plain_ok = (not explicit and digitcount <= 2)

        points = []
        for tok in tokens:
            val = parse_time_token(tok, plain_ok)
            if val is not None:
                points.append(val)
        return points

    def parse_time_value(value):
        if value is None:
            return None
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            iv = int(value)
            if iv == 24:
                return 1440
            if 0 <= iv < 24:
                return iv * 60
            if 25 <= iv < 100:
                return iv
            if 100 <= iv < 2400:
                h = iv // 100
                m = iv % 100
                if h < 24 and m < 60:
                    return h * 60 + m
            if 0 <= iv < 1440:
                return iv
            if iv == 1440:
                return 1440
            return None
        if isinstance(value, float):
            if int(value) == value:
                return parse_time_value(int(value))
            return None
        if isinstance(value, dict):
            for key in ["time", "datetime", "dateTime", "date_time", "value", "at", "start", "end"]:
                if key in value:
                    got = parse_time_value(value.get(key, None))
                    if got is not None:
                        return got
            for sub in value.values():
                got = parse_time_value(sub)
                if got is not None:
                    return got
            return None
        if isinstance(value, list) or isinstance(value, tuple):
            for sub in value:
                got = parse_time_value(sub)
                if got is not None:
                    return got
            return None

        pts = extract_time_points(value)
        if len(pts) > 0:
            return pts[0]
        return None

    def pair_from_string(text):
        raw = str(text).strip()
        if raw == "":
            return None
        low = raw.lower()

        for sep in [" to ", " until ", " thru ", " through "]:
            pos = low.find(sep)
            if pos >= 0:
                left = raw[:pos].strip()
                right = raw[pos + len(sep):].strip()
                a = parse_time_value(left)
                b = parse_time_value(right)
                if a is not None and b is not None:
                    return a, b

        pts = extract_time_points(raw)
        if len(pts) >= 2:
            s = pts[0]
            e = pts[1]
            if e < s:
                digitgroups = 0
                tmp = raw.replace("T", " ")
                for ch in [",", ";", "|", "(", ")", "[", "]", "{", "}", "<", ">", "\\", "/", "\n", "\r", "\t", "-", "–", "—", "~", "="]:
                    tmp = tmp.replace(ch, " ")
                parts = tmp.split()
                for part in parts:
                    if part.isdigit():
                        digitgroups += 1
                if ("T" in raw or "utc" in low or "gmt" in low or low.endswith("z") or raw.endswith("Z")) and digitgroups >= 3:
                    return None
                if (("-" in raw) or ("/" in raw) or ("." in raw)) and digitgroups >= 3:
                    return None
            return s, e

        return None

    def pick_value(obj, names):
        if not isinstance(obj, dict):
            return ""
        for name in names:
            if name in obj:
                val = obj.get(name, "")
                if val is not None:
                    return val
        return ""

    def pair_from_value(item):
        if item is None:
            return None
        if isinstance(item, bool):
            return None

        if isinstance(item, dict):
            for key in ["all_day", "allday", "full_day", "fullday", "is_all_day"]:
                if key in item:
                    val = item.get(key, None)
                    if isinstance(val, bool) and val:
                        return 0, 1440
                    if isinstance(val, int) and val != 0:
                        return 0, 1440
                    if isinstance(val, str) and val.strip().lower() in ["true", "yes", "1", "all", "full", "all_day", "fullday"]:
                        return 0, 1440

            start_names = ["start", "begin", "from", "start_time", "starttime", "start_at", "startdatetime", "start_date_time", "begin_at"]
            end_names = ["end", "finish", "to", "end_time", "endtime", "end_at", "enddatetime", "end_date_time", "finish_at"]
            duration_names = ["duration", "length", "minutes", "duration_minutes", "length_minutes", "mins"]

            s = pick_value(item, start_names)
            e = pick_value(item, end_names)
            d = pick_value(item, duration_names)

            if s != "" and e != "":
                sm = parse_time_value(s)
                em = parse_time_value(e)
                if sm is not None and em is not None:
                    return sm, em

            if s != "" and d != "":
                sm = parse_time_value(s)
                dm = parse_duration(d)
                if sm is not None and dm != 0:
                    return sm, sm + dm

            if e != "" and d != "":
                em = parse_time_value(e)
                dm = parse_duration(d)
                if em is not None and dm != 0:
                    return em - dm, em

            for sub in item.values():
                pair = pair_from_value(sub)
                if pair is not None:
                    return pair
            return None

        if isinstance(item, list) or isinstance(item, tuple):
            if len(item) == 2:
                a = parse_time_value(item[0])
                b = parse_time_value(item[1])
                if a is not None and b is not None:
                    return a, b
            for sub in item:
                pair = pair_from_value(sub)
                if pair is not None:
                    return pair
            return None

        if isinstance(item, str):
            return pair_from_string(item)

        if isinstance(item, int) or isinstance(item, float):
            return None

        return None

    def collect_ranges(value):
        ranges = []
        if isinstance(value, str):
            txt = value.strip().replace(";", ",")
            pieces = txt.split(",")
            for piece in pieces:
                pair = pair_from_value(piece)
                if pair is not None:
                    ranges.append(pair)
        elif isinstance(value, dict):
            pair = pair_from_value(value)
            if pair is not None:
                ranges.append(pair)
            else:
                for sub in value.values():
                    subranges = collect_ranges(sub)
                    for pair in subranges:
                        ranges.append(pair)
        elif isinstance(value, list) or isinstance(value, tuple):
            pair = pair_from_value(value)
            if pair is not None:
                ranges.append(pair)
            else:
                for item in value:
                    subranges = collect_ranges(item)
                    for pair in subranges:
                        ranges.append(pair)
        return ranges

    def collect_buffers(item, mode, skip_events):
        before = 0
        after = 0

        if isinstance(item, dict):
            for key, val in item.items():
                name = str(key).lower().strip()
                if skip_events and (name == "events" or name == "busy" or name == "meetings" or name == "appointments"):
                    continue

                nextmode = mode
                if "before" in name or name.startswith("pre") or "lead" in name:
                    nextmode = "before"
                elif "after" in name or name.startswith("post") or "lag" in name:
                    nextmode = "after"
                elif "buffer" in name or "padding" in name or "gap" in name or "spacing" in name or "transition" in name:
                    nextmode = "both"

                if isinstance(val, bool):
                    continue

                amount = 0
                if isinstance(val, int):
                    amount = val
                elif isinstance(val, float):
                    amount = int(val)
                elif isinstance(val, str):
                    amount = parse_duration(val)

                if amount != 0:
                    if nextmode == "before":
                        before += amount
                    elif nextmode == "after":
                        after += amount
                    else:
                        before += amount
                        after += amount

                if isinstance(val, dict) or isinstance(val, list) or isinstance(val, tuple):
                    b, a = collect_buffers(val, nextmode, skip_events)
                    before += b
                    after += a

        elif isinstance(item, list) or isinstance(item, tuple):
            for val in item:
                b, a = collect_buffers(val, mode, skip_events)
                before += b
                after += a

        return before, after

    def pick_workvalue(container, day):
        if not isinstance(container, dict):
            return ""
        aliases = day_aliases(day)
        work_names = ["working_hours", "work_hours", "workinghours", "workhours", "hours", "availability", "schedule"]

        for alias in aliases:
            if alias in container:
                val = container.get(alias, "")
                if val is not None:
                    return val

        for key in work_names:
            if key in container:
                val = container.get(key, "")
                if val is not None:
                    if isinstance(val, dict):
                        for alias in aliases:
                            if alias in val:
                                sub = val.get(alias, "")
                                if sub is not None:
                                    return sub
                    return val
        return ""

    def pick_events(container, day):
        if not isinstance(container, dict):
            return None
        aliases = day_aliases(day)
        event_names = ["events", "busy", "meetings", "appointments", "items"]

        for alias in aliases:
            if alias in container:
                val = container.get(alias, None)
                if val is not None:
                    return val

        for key in event_names:
            if key in container:
                val = container.get(key, None)
                if val is not None:
                    if isinstance(val, dict):
                        for alias in aliases:
                            if alias in val:
                                sub = val.get(alias, None)
                                if sub is not None:
                                    return sub
                    return val
        return None

    def select_day_record(cal, day):
        if not isinstance(cal, dict):
            return None
        daysvalue = cal.get("days", [])
        if not isinstance(daysvalue, list):
            return None
        aliases = day_aliases(day)
        for rec in daysvalue:
            if not isinstance(rec, dict):
                continue
            for key in ["day", "weekday", "name", "date"]:
                if key in rec:
                    val = str(rec.get(key, "")).strip().lower()
                    for alias in aliases:
                        if val == alias:
                            return rec
            for alias in aliases:
                if alias in rec:
                    return rec
        for rec in daysvalue:
            if isinstance(rec, dict):
                return rec
        return None

    def interval_duration(start, end):
        if end < start:
            return 1440 - start + end
        return end - start

    def interval_parts(start, end):
        parts = []
        if end <= 0 or start >= 1440:
            return parts
        if start < 0:
            if end > 1440:
                parts.append((0, 1440))
            elif end > 0:
                parts.append((0, end))
            return parts
        if end > 1440:
            parts.append((start, 1440))
            parts.append((0, end - 1440))
            return parts
        if end > start:
            parts.append((start, end))
        return parts

    def interval_fits(parts, start, end):
        for partstart, partend in parts:
            if start >= partstart and end <= partend:
                return True
        return False

    def intervals_overlap(parts, start, end):
        for partstart, partend in parts:
            if start < partend and end > partstart:
                return True
        return False

    def has_items(value):
        if value is None:
            return False
        if isinstance(value, str):
            return str(value).strip() != ""
        if isinstance(value, list) or isinstance(value, tuple) or isinstance(value, dict):
            return len(value) > 0
        return True

    def append_source(target, source):
        if source is None:
            return
        if isinstance(source, list) or isinstance(source, tuple):
            for item in source:
                target.append(item)
        elif isinstance(source, dict):
            for val in source.values():
                if isinstance(val, list) or isinstance(val, tuple):
                    for item in val:
                        target.append(item)
                else:
                    target.append(val)
        else:
            target.append(source)

    try:
        minutes = int(minutes)
    except Exception:
        return {"starts": []}

    if minutes < 0 or len(days) == 0:
        return {"starts": []}

    earliest = str(earliest).strip()
    latest_end = str(latest_end).strip()

    lower = 0
    if earliest != "":
        got = parse_time_value(earliest)
        if got is None:
            return {"starts": []}
        lower = got
    if lower < 0:
        lower = 0

    upper = 1440 - minutes
    if latest_end != "":
        got = parse_time_value(latest_end)
        if got is None:
            return {"starts": []}
        upper = got - minutes

    if upper > 1439:
        upper = 1439
    if upper < 0:
        return {"starts": []}

    start = lower
    rem = start % 15
    if rem != 0:
        start += 15 - rem
    last = upper - (upper % 15)
    if last > 1435:
        last = 1435

    if start > last:
        return {"starts": []}

    common = None

    for day in days:
        usercal = api.read_calendar("", day)
        if not isinstance(usercal, dict):
            return {"starts": []}
        useroffset = parse_offset(usercal.get("utc_offset", ""))
        userinfo = None

        workvalue = pick_workvalue(usercal, day)
        workranges = []
        if has_items(workvalue):
            workranges = collect_ranges(workvalue)

        dayrec = select_day_record(usercal, day)
        if dayrec is not None:
            recwork = pick_workvalue(dayrec, day)
            if has_items(recwork):
                recranges = collect_ranges(recwork)
                if len(recranges) > 0:
                    workranges = recranges

        if len(workranges) == 0:
            workparts = [(0, 1440)]
        else:
            workparts = []
            for pair in workranges:
                if pair is None:
                    continue
                localstart = pair[0]
                localend = pair[1]
                if localstart is None or localend is None:
                    continue
                shiftedstart = localstart + useroffset - useroffset
                duration = interval_duration(localstart, localend)
                parts = interval_parts(shiftedstart, shiftedstart + duration)
                for part in parts:
                    workparts.append(part)

        defaultbefore, defaultafter = collect_buffers(usercal, "", True)

        eventsvalue = []
        root_events = pick_events(usercal, day)
        if has_items(root_events):
            append_source(eventsvalue, root_events)

        if dayrec is not None:
            day_events = pick_events(dayrec, day)
            if has_items(day_events):
                append_source(eventsvalue, day_events)

        infos = [{"workparts": workparts, "busy": []}]

        for person in attendees:
            cal = api.read_calendar(person, day)
            if not isinstance(cal, dict):
                return {"starts": []}
            personoffset = parse_offset(cal.get("utc_offset", ""))

            info = None
            workvalue = pick_workvalue(cal, day)
            workranges = []
            if has_items(workvalue):
                workranges = collect_ranges(workvalue)

            dayrec = select_day_record(cal, day)
            if dayrec is not None:
                recwork = pick_workvalue(dayrec, day)
                if has_items(recwork):
                    recranges = collect_ranges(recwork)
                    if len(recranges) > 0:
                        workranges = recranges

            if len(workranges) == 0:
                workparts = [(0, 1440)]
            else:
                workparts = []
                for pair in workranges:
                    if pair is None:
                        continue
                    localstart = pair[0]
                    localend = pair[1]
                    if localstart is None or localend is None:
                        continue
                    shiftedstart = localstart + useroffset - personoffset
                    duration = interval_duration(localstart, localend)
                    parts = interval_parts(shiftedstart, shiftedstart + duration)
                    for part in parts:
                        workparts.append(part)

            busy = []
            raw_events = []
            root_events = pick_events(cal, day)
            if has_items(root_events):
                append_source(raw_events, root_events)
            if dayrec is not None:
                day_events = pick_events(dayrec, day)
                if has_items(day_events):
                    append_source(raw_events, day_events)

            if not isinstance(raw_events, list):
                raw_events = list(raw_events)

            for ev in raw_events:
                if not isinstance(ev, dict):
                    continue

                state = ""
                for key in ["show_as", "status", "availability"]:
                    if key in ev:
                        state = str(ev.get(key, "")).lower().strip()
                        break
                if state == "free" or state == "available" or state == "open":
                    continue

                busyflag = ev.get("busy", None)
                if isinstance(busyflag, bool) and busyflag is False:
                    continue
                if isinstance(busyflag, str) and busyflag.strip().lower() in ["false", "no", "0", "free", "available"]:
                    continue
                if isinstance(busyflag, int) and busyflag == 0:
                    continue

                before, after = collect_buffers(ev, "", False)
                before += defaultbefore
                after += defaultafter

                times = pair_from_value(ev)
                if times is None:
                    continue

                evstartlocal = times[0]
                evendlocal = times[1]
                if evstartlocal is None or evendlocal is None:
                    continue

                evstart = evstartlocal + useroffset - personoffset - before
                evend = evendlocal + useroffset - personoffset + after
                evlen = interval_duration(evstartlocal - before, evendlocal + after)
                parts = interval_parts(evstart, evstart + evlen)
                for part in parts:
                    busy.append(part)

            infos.append({"workparts": workparts, "busy": busy})

        candidate = start
        daystarts = []
        while candidate <= last:
            end = candidate + minutes
            ok = True
            for info in infos:
                if not interval_fits(info["workparts"], candidate, end):
                    ok = False
                    break
                if intervals_overlap(info["busy"], candidate, end):
                    ok = False
                    break
            if ok:
                daystarts.append(to_time(candidate))
            candidate += 15

        if common is None:
            common = daystarts
        else:
            dayset = set(daystarts)
            newcommon = []
            for t in common:
                if t in dayset:
                    newcommon.append(t)
            common = newcommon

        if len(common) == 0:
            return {"starts": []}

    if common is None:
        common = []

    return {"starts": common}
