def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def time_to_minutes(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def minutes_to_time(total):
        hour, minute = divmod(total, 60)
        return str(hour).rjust(2, "0") + ":" + str(minute).rjust(2, "0")

    def offset_to_minutes(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        if text[0] == "+" or text[0] == "-":
            text = text[1:]
        parts = text.split(":")
        return sign * (int(parts[0]) * 60 + int(parts[1]))

    def parse_window(text):
        parts = text.split("-")
        return time_to_minutes(parts[0]), time_to_minutes(parts[1])

    def round_up_quarter(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def record_from_calendar(calendar, user_offset):
        offset = offset_to_minutes(calendar["utc_offset"])
        shift = user_offset - offset
        work_start, work_end = parse_window(calendar["working_hours"])
        work_start = work_start + shift
        work_end = work_end + shift
        note = str(calendar.get("note", "")).lower()
        buffer_minutes = 15 if "15 minutes" in note else 0

        busy = []
        day_list = calendar.get("days", [])
        if len(day_list) > 0:
            events = day_list[0].get("events", [])
            for event in events:
                if event.get("show_as") != "free":
                    start = time_to_minutes(event["start"]) + shift - buffer_minutes
                    end = time_to_minutes(event["end"]) + shift + buffer_minutes
                    busy.append((start, end))

        return {"work_start": work_start, "work_end": work_end, "busy": busy}

    unique_attendees = []
    for name in attendees:
        if name not in unique_attendees:
            unique_attendees.append(name)

    day_records = {}
    for day in days:
        user_calendar = api.read_calendar("", day)
        user_offset = offset_to_minutes(user_calendar["utc_offset"])
        records = [record_from_calendar(user_calendar, user_offset)]
        for name in unique_attendees:
            calendar = api.read_calendar(name, day)
            records.append(record_from_calendar(calendar, user_offset))
        day_records[day] = records

    earliest_minutes = 0 if earliest == "" else time_to_minutes(earliest)
    latest_minutes = 24 * 60 if latest_end == "" else time_to_minutes(latest_end)

    start_minute = round_up_quarter(earliest_minutes)
    last_start = latest_minutes - minutes
    if last_start > 24 * 60 - minutes:
        last_start = 24 * 60 - minutes

    starts = []
    start = start_minute
    while start <= last_start:
        end = start + minutes
        valid = True
        for day in days:
            records = day_records[day]
            for record in records:
                if start < record["work_start"] or end > record["work_end"]:
                    valid = False
                    break
                for busy_start, busy_end in record["busy"]:
                    if start < busy_end and busy_start < end:
                        valid = False
                        break
                if not valid:
                    break
            if not valid:
                break
        if valid:
            starts.append(minutes_to_time(start))
        start += 15

    return {"starts": starts}
