def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    earliest = str(earliest).strip()
    latest_end = str(latest_end).strip()

    def normday(text):
        text = str(text).strip().lower()
        if len(text) > 3:
            return text[:3]
        return text

    def to_minutes(text):
        parts = str(text).strip().split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def from_minutes(value):
        return str(value // 60).zfill(2) + ":" + str(value % 60).zfill(2)

    def offset_minutes(text):
        text = str(text).strip()
        if not text:
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def parse_hours(text):
        parts = str(text).strip().split("-")
        return to_minutes(parts[0]), to_minutes(parts[1])

    def day_entry(calendar, daytext):
        target = normday(daytext)
        items = calendar.get("days", [])
        for item in items:
            if normday(item.get("day", "")) == target:
                return item
        if len(items) == 1:
            return items[0]
        return {"events": []}

    def buffer_for(calendar):
        note = str(calendar.get("note", "")).lower()
        if note.find("15 minutes") != -1 and note.find("between") != -1:
            return 15
        return 0

    def blocks(entry, buffer):
        result = []
        for event in entry.get("events", []):
            if str(event.get("show_as", "busy")).lower() == "free":
                continue
            start = to_minutes(event.get("start", "00:00")) - buffer
            end = to_minutes(event.get("end", "00:00")) + buffer
            result.append((start, end))
        return result

    def overlap(start, end, ranges):
        for a, b in ranges:
            if start < b and a < end:
                return True
        return False

    def quarter_up(value):
        r = value % 15
        if r == 0:
            return value
        return value + (15 - r)

    def quarter_down(value):
        return value - (value % 15)

    def info_for(person, daytext):
        calendar = api.read_calendar(person, daytext)
        entry = day_entry(calendar, daytext)
        wh0, wh1 = parse_hours(calendar.get("working_hours", "00:00-23:59"))
        return {
            "off": offset_minutes(calendar.get("utc_offset", "+00:00")),
            "wh0": wh0,
            "wh1": wh1,
            "blocks": blocks(entry, buffer_for(calendar)),
        }

    def valid(start, userinfo, otherinfos):
        end = start + minutes
        if start < userinfo["wh0"] or end > userinfo["wh1"]:
            return False
        if start < 0 or end > 1440:
            return False
        if overlap(start, end, userinfo["blocks"]):
            return False

        useroff = userinfo["off"]
        for person in otherinfos:
            local_start = start + (person["off"] - useroff)
            local_end = local_start + minutes
            if local_start < 0 or local_end > 1440:
                return False
            if local_start < person["wh0"] or local_end > person["wh1"]:
                return False
            if overlap(local_start, local_end, person["blocks"]):
                return False
        return True

    common = None

    for day in days:
        daytext = str(day).strip()
