        end_bound = userinfo["wh1"] - minutes
        if latest_end != "":
            end_bound = min(end_bound, to_minutes(latest_end) - minutes)

        start_bound = quarter_up(start_bound)
        end_bound = quarter_down(end_bound)

        daystarts = set()
        if end_bound >= start_bound:
            current = start_bound
            while current <= end_bound:
                if valid(current, userinfo, otherinfos):
                    daystarts.add(current)
                current += 15

        if common is None:
            common = daystarts
        else:
            common = common.intersection(daystarts)

        if not common:
            break

    if common is None:
        common = set()

