def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def timeToMinutes(text):
        return int(text[0:2]) * 60 + int(text[3:5])

    def minutesToTime(value):
        hour = value // 60
        minute = value % 60
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def offsetToMinutes(text):
        sign = 1
        if text[0] == "-":
            sign = -1
        return sign * (int(text[1:3]) * 60 + int(text[4:6]))

    def convertTime(text, userOffset, personOffset):
        return timeToMinutes(text) + offsetToMinutes(userOffset) - offsetToMinutes(personOffset)

    def parseRange(text):
        parts = text.split("-")
        return parts[0], parts[1]

    earliestMin = 0 if earliest == "" else timeToMinutes(earliest)
    latestMin = 24 * 60 if latest_end == "" else timeToMinutes(latest_end)

    schedule = {}

    for day in days:
        dayInfo = {}
        userData = api.read_calendar("", day)
        userOffset = userData["utc_offset"]

        userWorkStartText, userWorkEndText = parseRange(userData["working_hours"])
        dayInfo["userWorkStart"] = timeToMinutes(userWorkStartText)
        dayInfo["userWorkEnd"] = timeToMinutes(userWorkEndText)

        userBusy = []
        userDayList = userData["days"]
        if len(userDayList) > 0:
            for event in userDayList[0]["events"]:
                if event.get("show_as", "busy") != "free":
                    userBusy.append((timeToMinutes(event["start"]), timeToMinutes(event["end"])))
        dayInfo["userBusy"] = userBusy

        people = []
        for person in attendees:
            personData = api.read_calendar(person, day)
            personOffset = personData["utc_offset"]

            pad = 0
            if "note" in personData and "15 minutes" in personData["note"]:
                pad = 15

            workStartText, workEndText = parseRange(personData["working_hours"])
            workStart = convertTime(workStartText, userOffset, personOffset)
            workEnd = convertTime(workEndText, userOffset, personOffset)

            busy = []
            personDayList = personData["days"]
            if len(personDayList) > 0:
                for event in personDayList[0]["events"]:
                    if event.get("show_as", "busy") != "free":
                        start = convertTime(event["start"], userOffset, personOffset) - pad
                        end = convertTime(event["end"], userOffset, personOffset) + pad
                        busy.append((start, end))

            people.append((workStart, workEnd, busy))

        dayInfo["people"] = people
        schedule[day] = dayInfo

    starts = []
    lastStart = 24 * 60 - minutes
    if lastStart < 0:
        lastStart = -1

    for start in range(0, lastStart + 1, 15):
        if start < earliestMin:
            continue
        if start + minutes > latestMin:
            continue

        end = start + minutes
        ok = True

        for day in days:
            dayInfo = schedule[day]

            if start < dayInfo["userWorkStart"] or end > dayInfo["userWorkEnd"]:
                ok = False
                break

            for busy in dayInfo["userBusy"]:
                if start < busy[1] and end > busy[0]:
                    ok = False
                    break
            if not ok:
                break

            for personInfo in dayInfo["people"]:
                workStart, workEnd, busyList = personInfo

                if start < workStart or end > workEnd:
                    ok = False
                    break

                for busy in busyList:
                    if start < busy[1] and end > busy[0]:
                        ok = False
                        break
                if not ok:
                    break

            if not ok:
                break

        if ok:
            starts.append(minutesToTime(start))

    return {"starts": starts}
