def find_common_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(value):
        if isinstance(value, int):
            return value
        if value is None:
            return None
        text = str(value).strip()
        if not text:
            return None
        if "T" in text:
            text = text.rsplit("T", 1)[1]
        if " " in text:
            text = text.rsplit(" ", 1)[1]
        if text.endswith("Z"):
            text = text[:-1]
        parts = text.split(":")
        if len(parts) < 2:
            return None
        try:
            hour = int(parts[0])
            minute = int(parts[1])
        except Exception:
            return None
        return hour * 60 + minute

    def fmt_time(total_minutes):
        hour = total_minutes // 60
        minute = total_minutes % 60
        return str(hour).zfill(2) + ":" + str(minute).zfill(2)

    def ceil_quarter(total_minutes):
        return ((total_minutes + 14) // 15) * 15

    def add_interval(intervals, start, end):
        if start is None or end is None:
            return
        if start == end:
            return
        if end < start:
            if start < 1440:
                intervals.append((max(0, start), 1440))
            if end > 0:
                intervals.append((0, min(1440, end)))
            return
        intervals.append((max(0, start), min(1440, end)))

    def collect_intervals(data, intervals):
        if data is None:
            return

        if isinstance(data, list) or isinstance(data, tuple):
            if len(data) == 2 and not isinstance(data[0], (list, tuple, dict)) and not isinstance(data[1], (list, tuple, dict)):
                add_interval(intervals, parse_time(data[0]), parse_time(data[1]))
                return
            for item in data:
                collect_intervals(item, intervals)
            return

        if isinstance(data, dict):
            status = data.get("status")
            if isinstance(status, str):
                low = status.lower()
                if low == "free" or low == "available":
                    return

            if "start" in data or "end" in data or "start_time" in data or "end_time" in data or "from" in data or "to" in data:
                start = data.get("start", data.get("start_time", data.get("from", data.get("begin"))))
                end = data.get("end", data.get("end_time", data.get("to", data.get("finish"))))
                if isinstance(start, dict):
                    start = start.get("time", start.get("dateTime", start.get("datetime", start.get("value"))))
                if isinstance(end, dict):
                    end = end.get("time", end.get("dateTime", end.get("datetime", end.get("value"))))
                add_interval(intervals, parse_time(start), parse_time(end))
                return

            for key in ("busy", "events", "calendar", "items", "entries", "slots"):
                if key in data:
                    collect_intervals(data[key], intervals)

            for value in data.values():
                if isinstance(value, (list, tuple, dict)):
                    collect_intervals(value, intervals)
            return

        if isinstance(data, str):
            text = data.strip()
            if "-" in text:
                parts = text.split("-")
                if len(parts) >= 2:
                    add_interval(intervals, parse_time(parts[0]), parse_time(parts[1]))
            return

    def merge(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [list(intervals[0])]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        return [(start, end) for start, end in merged]

    def available_starts(busy, lower_bound, upper_bound, duration):
        starts = []
        first = ceil_quarter(lower_bound)
        last = upper_bound - duration
        current = first
        while current <= last:
            end = current + duration
            ok = True
            for busy_start, busy_end in busy:
                if current < busy_end and end > busy_start:
                    ok = False
                    break
            if ok:
                starts.append(current)
            current += 15
        return starts

    lower_bound = parse_time(earliest) if earliest else 0
    upper_bound = parse_time(latest_end) if latest_end else 1440
    if lower_bound is None:
        lower_bound = 0
    if upper_bound is None:
        upper_bound = 1440

    if lower_bound < 0:
        lower_bound = 0
    if upper_bound < 0:
        upper_bound = 0
    if lower_bound > 1440:
        lower_bound = 1440
    if upper_bound > 1440:
        upper_bound = 1440
    if minutes < 0:
        minutes = 0

    people = [""]
    if attendees:
        people += attendees

    common = None
    if days:
        for day in days:
            busy = []
            for person in people:
                calendar = api.read_calendar(person, day)
                collect_intervals(calendar, busy)
            busy = merge(busy)
            starts = available_starts(busy, lower_bound, upper_bound, minutes)
            if common is None:
                common = set(starts)
            else:
                common &= set(starts)
            if not common:
                break
    else:
        common = set(available_starts([], lower_bound, upper_bound, minutes))

    if common is None:
        common = set()

    return {"starts": [fmt_time(m) for m in sorted(common)]}
