        merged = [intervals[0]]
        for s, e in intervals[1:]:
            last_s, last_e = merged[-1]
            if s <= last_e:
                if e > last_e:
                    merged[-1] = (last_s, e)
            else:
                merged.append((s, e))
        return merged

    def is_free(start_m: int, end_m: int, busy: list) -> bool:
        for s, e in busy:
            if start_m < e and end_m > s:
                return False
        return True

    result = {"starts": {}}
