                        s = to_minutes(ev.get("start", ""))
                        e = to_minutes(ev.get("end", ""))
                        if s >= 0 and e >= 0 and e > s:
                            all_busy.append((s, e))

        if earliest_m >= 0 and earliest_m > window_start:
            window_start = earliest_m
        if latest_m >= 0 and latest_m < window_end:
            window_end = latest_m

        all_busy = merge_busy(all_busy)

        starts = []
        start_m = ceil_quarter(window_start)
        while start_m + minutes <= window_end:
            if is_free(start_m, start_m + minutes, all_busy):
                starts.append(to_time(start_m))
            start_m += 15

        if starts:
            result["starts"][day] = starts

    return result
