        m = total % 60
        return str(h).zfill(2) + ":" + str(m).zfill(2)

    def _parse_offset(offset: str) -> int:
        sign = -1 if offset and offset[0] == "-" else 1
        return sign * (_to_minutes(offset[1:]) if offset else 0)

    def _day_offset(user_offset: int, person_offset: int) -> int:
        return person_offset - user_offset

    def _overlaps(a_start: int, a_end: int, b_start: int, b_end: int) -> bool:
        return a_start < b_end and b_start < a_end

    result = {"starts": {}}
    user_info = api.read_calendar("", days[0] if days else "")
    user_offset = _parse_offset(user_info.get("utc_offset", "-00:00"))

