        user_work = user_day.get("working_hours", "00:00-23:59")
        wh_start = _to_minutes(user_work[:5])
        wh_end = _to_minutes(user_work[6:11])

        window_start = wh_start
        if earliest != "":
            window_start = max(window_start, _to_minutes(earliest))

