            shift = _day_offset(user_offset, person_offset)
            entries = cal.get("days", [])
            if len(entries) == 0:
                continue
            evs = entries[0].get("events", [])
            for ev in evs:
                if ev.get("show_as", "") == "busy":
                    s = _to_minutes(ev["start"]) - shift * 60
                    e = _to_minutes(ev["end"]) - shift * 60
                    busy.append((s, e))

        starts = []
        last_start = window_end
        t = window_start
        while t <= last_start:
            ok = True
            if t % 15 != 0:
                t += 15 - (t % 15)
                continue
            for b in busy:
                if _overlaps(t, t + minutes, b[0], b[1]):
                    ok = False
                    break
            if ok:
                starts.append(_to_hhmm(t))
            t += 15

        if len(starts) > 0:
            result["starts"][day] = starts

    return result
