    def _min_to_hm(m: int) -> str:
        h = m // 60
        mm = m % 60
        return ("0" if h < 10 else "") + str(h) + ":" + ("0" if mm < 10 else "") + str(mm)

    def _parse_offset(s: str) -> int:
        sign = -1 if s[0] == "-" else 1
        return sign * (int(s[1:3]) * 60 + int(s[4:6]))

    def _day_map(cal: dict) -> dict:
