        person_days[person] = _day_map(cal)
        wh = cal.get("working_hours", "00:00-23:59")
        person_work[person] = (_hm_to_min(wh[:5]), _hm_to_min(wh[6:11]))

    earliest_min = _hm_to_min(earliest) if earliest else 0
    latest_min = _hm_to_min(latest_end) if latest_end else 24 * 60

    starts = {}
    for day in days:
        busy = []

        if day in user_days:
            for ev in user_days[day].get("events", []):
