                    s = _hm_to_min(ev.get("start", "00:00")) + delta
                    e = _hm_to_min(ev.get("end", "00:00")) + delta
                    busy.append((s, e))

        busy = sorted(busy)
        merged = []
        for s, e in busy:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
                if e > merged[-1][1]:
                    merged[-1][1] = e

        day_start = user_work_start
        day_end = user_work_end
