        day_starts = []
        t = day_start
        while t + minutes <= day_end:
            q = t % 15
            if q != 0:
                t += 15 - q
                continue

            free = True
            for s, e in merged:
                if t < e and t + minutes > s:
                    free = False
                    break
            if free:
                day_starts.append(_min_to_hm(t))
            t += 15

        if day_starts:
            starts[day] = day_starts

    return {"starts": starts}
