                shift = my_offset - person_offset

                wh = cal["working_hours"]
                wh_start = hm_to_min(wh[:5]) + shift
                wh_end = hm_to_min(wh[6:11]) + shift
                if start < wh_start or end > wh_end:
                    free = False
                    break

                for ev in item["events"]:
                    ev_start = hm_to_min(ev["start"]) + shift
                    ev_end = hm_to_min(ev["end"]) + shift
                    if ev.get("show_as") == "busy":
