    def to_minutes(t: str) -> int:
        if not t:
            return -1
        parts = t.split(":")
        if len(parts) != 2:
            return -1
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(m: int) -> str:
        h = m // 60
        mm = m % 60
        return str(h).zfill(2) + ":" + str(mm).zfill(2)

    def ceil_quarter(m: int) -> int:
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def parse_working_hours(s: str) -> tuple:
        if not s or "-" not in s:
            return (0, 24 * 60)
        a, b = s.split("-")
        return (to_minutes(a), to_minutes(b))

    def parse_offset_text(text: str) -> int:
        if not text:
            return 0
        t = text.strip()
        if not t:
            return 0
        if "UTC" in t:
            t = t.replace("UTC", "")
        if "GMT" in t:
            t = t.replace("GMT", "")
        t = t.strip()
        if not t:
            return 0
        sign = 1
        if t[0] == "+":
            t = t[1:]
        elif t[0] == "-":
            sign = -1
            t = t[1:]
        t = t.strip()
        if not t:
            return 0
        if ":" in t:
            a, b = t.split(":")
            return sign * (int(a) * 60 + int(b))
        if len(t) in (3, 4):
            if len(t) == 3:
                return sign * (int(t[0]) * 60 + int(t[1:]))
            return sign * (int(t[:2]) * 60 + int(t[2:]))
        return sign * (int(t) * 60)

    def get_offset(cal: dict) -> int:
        keys = (
            "utc_offset", "utcOffset", "timezone_offset", "time_zone_offset",
            "offset", "tz_offset", "timeZoneOffset"
        )
        for k in keys:
            if k in cal:
                v = cal.get(k)
                if isinstance(v, int):
                    return v
                if isinstance(v, str):
                    return parse_offset_text(v)
        keys2 = ("time_zone", "timezone", "timeZone", "tz")
        for k in keys2:
            if k in cal:
                v = cal.get(k)
                if isinstance(v, str):
                    return parse_offset_text(v)
        return 0

    def day_items_from_calendar(cal: dict) -> list:
        days_list = cal.get("days", [])
        if days_list:
            return days_list
        items = cal.get("events", [])
        if items:
            return [{"events": items}]
        return []

    def convert_to_user_clock(m: int, person_offset: int, user_offset: int) -> int:
        return m + (user_offset - person_offset)

    def merge_busy(intervals: list) -> list:
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for s, e in intervals[1:]:
            last_s, last_e = merged[-1]
            if s <= last_e:
                if e > last_e:
                    merged[-1] = (last_s, e)
            else:
                merged.append((s, e))
        return merged

    def is_free(start_m: int, end_m: int, busy: list) -> bool:
        for s, e in busy:
            if start_m < e and end_m > s:
                return False
        return True

    def collect_busy_and_window(person: str, day: str, user_offset: int):
        cal = api.read_calendar(person, day)
        person_offset = get_offset(cal)
        window_start = 0
        window_end = 24 * 60
        busy = []

        wh = cal.get("working_hours", "")
        if wh:
            ws, we = parse_working_hours(wh)
            if ws >= 0 and we >= 0:
                ws = convert_to_user_clock(ws, person_offset, user_offset)
                we = convert_to_user_clock(we, person_offset, user_offset)
                if ws > window_start:
                    window_start = ws
                if we < window_end:
                    window_end = we

        for day_item in day_items_from_calendar(cal):
            events = day_item.get("events", [])
            for ev in events:
                if ev.get("show_as") == "busy":
                    s = to_minutes(ev.get("start", ""))
                    e = to_minutes(ev.get("end", ""))
                    if s >= 0 and e >= 0 and e > s:
                        s = convert_to_user_clock(s, person_offset, user_offset)
                        e = convert_to_user_clock(e, person_offset, user_offset)
                        busy.append((s, e))
        return window_start, window_end, busy

    result = {"starts": {}}
    earliest_m = to_minutes(earliest) if earliest else -1
    latest_m = to_minutes(latest_end) if latest_end else -1

    user_offset = get_offset(api.read_calendar("", days[0])) if days else 0

    people = [""] + attendees
    for day in days:
        all_busy = []
        window_start = 0
        window_end = 24 * 60

        for person in people:
            ps, pe, busy = collect_busy_and_window(person, day, user_offset)
            if ps > window_start:
                window_start = ps
            if pe < window_end:
                window_end = pe
            for item in busy:
                all_busy.append(item)

        if earliest_m >= 0 and earliest_m > window_start:
            window_start = earliest_m
        if latest_m >= 0 and latest_m < window_end:
            window_end = latest_m

        all_busy = merge_busy(all_busy)

        starts = []
        start_m = ceil_quarter(window_start)
        while start_m + minutes <= window_end:
            if is_free(start_m, start_m + minutes, all_busy):
                starts.append(to_time(start_m))
            start_m += 15

        if starts:
            result["starts"][day] = starts

    return result
