        for s, e in busy:
            if start_m < e and end_m > s:
                return False
        return True

    def collect_busy_and_window(person: str, day: str, user_offset: int):
        cal = api.read_calendar(person, day)
        person_offset = get_offset(cal)

        window_start = 0
        window_end = 24 * 60
