    def to_minutes(t: str) -> int:
        if not t:
            return -1
        parts = t.split(":")
        if len(parts) != 2:
            return -1
        try:
            return int(parts[0]) * 60 + int(parts[1])
        except Exception:
            return -1

    def to_time(m: int) -> str:
        return str(m // 60).zfill(2) + ":" + str(m % 60).zfill(2)

    def ceil_quarter(m: int) -> int:
        r = m % 15
        if r == 0:
            return m
        return m + (15 - r)

    def parse_working_hours(s: str) -> tuple:
        if not s or "-" not in s:
            return (0, 24 * 60)
        parts = s.split("-")
        if len(parts) != 2:
            return (0, 24 * 60)
        a = to_minutes(parts[0].strip())
        b = to_minutes(parts[1].strip())
        if a < 0 or b < 0:
            return (0, 24 * 60)
        return (a, b)

    def parse_offset_text(text: str) -> int:
        if not text:
            return 0
        t = text.strip()
        if not t:
            return 0
        t = t.replace("UTC", "").replace("GMT", "").strip()
        if not t:
            return 0
        sign = 1
        if t[0] == "+":
            t = t[1:]
        elif t[0] == "-":
            sign = -1
            t = t[1:]
        t = t.strip()
        if not t:
            return 0
        if ":" in t:
            parts = t.split(":")
            if len(parts) != 2:
                return 0
            return sign * (int(parts[0]) * 60 + int(parts[1]))
        if len(t) == 3:
            return sign * (int(t[0]) * 60 + int(t[1:]))
        if len(t) == 4:
            return sign * (int(t[:2]) * 60 + int(t[2:]))
        return sign * (int(t) * 60)

    def get_offset(cal: dict) -> int:
        keys = ("utc_offset", "utcOffset", "timezone_offset", "time_zone_offset",
                "offset", "tz_offset", "timeZoneOffset")
        for k in keys:
            if k in cal:
                v = cal.get(k)
                if isinstance(v, int):
                    return v
                if isinstance(v, str):
                    return parse_offset_text(v)
        keys2 = ("time_zone", "timezone", "timeZone", "tz")
        for k in keys2:
            if k in cal:
                v = cal.get(k)
                if isinstance(v, str):
                    return parse_offset_text(v)
        return 0

    def convert_to_user_clock(m: int, person_offset: int, user_offset: int) -> int:
        return m + (user_offset - person_offset)

    def clamp_day(m: int) -> int:
        if m < 0:
            return 0
        if m > 24 * 60:
            return 24 * 60
        return m

    def buffer_from_value(v) -> tuple:
        if isinstance(v, int):
            if v < 0:
                v = 0
            return (v, v)
        if isinstance(v, dict):
            before = 0
            after = 0
            for k in ("before", "pre", "start", "leading"):
                if k in v and isinstance(v.get(k), int):
                    before = v.get(k)
                    break
            for k in ("after", "post", "end", "trailing"):
                if k in v and isinstance(v.get(k), int):
                    after = v.get(k)
                    break
            if before == 0 and after == 0:
                for k in ("minutes", "buffer", "value"):
                    if k in v and isinstance(v.get(k), int):
                        before = v.get(k)
                        after = v.get(k)
                        break
            if before < 0:
                before = 0
            if after < 0:
                after = 0
            return (before, after)
        return (0, 0)

    def get_event_buffer(ev: dict, cal: dict) -> tuple:
        for k in ("buffer", "buffers", "meeting_buffer", "meetingBuffer"):
            if k in ev:
                return buffer_from_value(ev.get(k))
        for k in ("buffer", "buffers", "meeting_buffer", "meetingBuffer"):
            if k in cal:
                return buffer_from_value(cal.get(k))
        return (0, 0)

    def day_items_from_calendar(cal: dict) -> list:
        d = cal.get("days", [])
        if d:
            return d
        e = cal.get("events", [])
        if e:
            return [{"events": e}]
        return []

    def merge_busy(intervals: list) -> list:
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for s, e in intervals[1:]:
            ls, le = merged[-1]
            if s <= le:
                if e > le:
                    merged[-1] = (ls, e)
            else:
                merged.append((s, e))
        return merged

    def is_free(start_m: int, end_m: int, busy: list) -> bool:
        for s, e in busy:
            if start_m < e and end_m > s:
                return False
        return True

    def collect_busy_and_window(person: str, day: str, user_offset: int):
        cal = api.read_calendar(person, day)
        person_offset = get_offset(cal)

        window_start = 0
        window_end = 24 * 60
        busy = []

