def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def norm_day(d):
        s = str(d).strip().lower()
        if len(s) >= 3:
            s = s[:3]
        if s == "mon":
            return "mon"
        if s == "tue":
            return "tue"
        if s == "wed":
            return "wed"
        if s == "thu":
            return "thu"
        if s == "fri":
            return "fri"
        return s

    def parse_time(t):
        parts = str(t).split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def fmt_time(m):
        h = m // 60
        mm = m % 60
        if h < 10:
            hs = "0" + str(h)
        else:
            hs = str(h)
        if mm < 10:
            ms = "0" + str(mm)
        else:
            ms = str(mm)
        return hs + ":" + ms

    def offset_minutes(off):
        s = str(off).strip()
        sign = 1
        if len(s) > 0 and s[0] == "-":
            sign = -1
            s = s[1:]
        elif len(s) > 0 and s[0] == "+":
            s = s[1:]
        p = s.split(":")
        return sign * (int(p[0]) * 60 + int(p[1]))

    def overlaps(a1, a2, b1, b2):
        return a1 < b2 and b1 < a2

    def get_day_record(calendar, day_key):
        ds = calendar.get("days", [])
        for item in ds:
            if str(item.get("day", "")).lower() == day_key:
                return item
        return None

    def local_to_user_min(local_min, person_offset, user_offset):
        return local_min + (user_offset - person_offset)

    def busy_intervals_for_person(person, day_key, user_offset):
        cal = api.read_calendar(person, day_key)
        person_offset = offset_minutes(cal.get("utc_offset", "+00:00"))
        dayrec = get_day_record(cal, day_key)
        intervals = []
        if dayrec is None:
            return intervals
        note = str(cal.get("note", ""))
        add_buffer = 15 if "leave 15 minutes between any meeting with me and my other meetings" in note.lower() else 0
        events = dayrec.get("events", [])
        for ev in events:
            if str(ev.get("show_as", "")).lower() != "busy":
                continue
            s = local_to_user_min(parse_time(ev.get("start", "00:00")), person_offset, user_offset)
            e = local_to_user_min(parse_time(ev.get("end", "00:00")), person_offset, user_offset)
            s = s - add_buffer
            e = e + add_buffer
            intervals.append((s, e))
        return intervals

    result = {"starts": {}}
    day_list = []
    for d in days:
        nd = norm_day(d)
        if nd in ("mon", "tue", "wed", "thu", "fri"):
            day_list.append(nd)

    if len(day_list) == 0 or minutes <= 0:
        return result

    user_cal = api.read_calendar("", day_list[0])
    user_offset = offset_minutes(user_cal.get("utc_offset", "+00:00"))

    earliest_min = 0
    latest_end_min = 24 * 60
    if earliest != "":
        earliest_min = parse_time(earliest)
    if latest_end != "":
        latest_end_min = parse_time(latest_end)

    for day_key in day_list:
        user_cal = api.read_calendar("", day_key)
        user_offset = offset_minutes(user_cal.get("utc_offset", "+00:00"))
        user_day = get_day_record(user_cal, day_key)
        if user_day is None:
            continue

        blocked = []
        for ev in user_day.get("events", []):
            if str(ev.get("show_as", "")).lower() == "busy":
                blocked.append((parse_time(ev.get("start", "00:00")), parse_time(ev.get("end", "00:00"))))

        for person in attendees:
            person_blocks = busy_intervals_for_person(person, day_key, user_offset)
            for b in person_blocks:
                blocked.append(b)

        starts = []
        t = earliest_min
        last_start = latest_end_min - minutes
        while t <= last_start:
            end_t = t + minutes
            ok = True
            if latest_end != "" and end_t > latest_end_min:
                ok = False
            if ok:
                for b in blocked:
                    if overlaps(t, end_t, b[0], b[1]):
                        ok = False
                        break
            if ok:
                starts.append(fmt_time(t))
            t += 15

        if len(starts) > 0:
            result["starts"][day_key] = starts

    return result
