def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_min(t: str) -> int:
        p = t.split(":")
        return int(p[0]) * 60 + int(p[1])

    def to_time(m: int) -> str:
        h = m // 60
        mm = m - h * 60
        return str(h).rjust(2, "0") + ":" + str(mm).rjust(2, "0")

    def merge_busy(events):
        busy = []
        for e in events:
            if e.get("show_as", "busy") != "free":
                s = to_min(e["start"])
                en = to_min(e["end"])
                busy.append((s, en))
        busy = sorted(busy)
        merged = []
        for s, e in busy:
            if not merged or s > merged[-1][1]:
                merged.append([s, e])
            else:
                if e > merged[-1][1]:
                    merged[-1][1] = e
        return merged

    def free_at(start_m, end_m, busy):
        for s, e in busy:
            if start_m < e and start_m + minutes > s:
                return False
        return start_m + minutes <= end_m

    starts_by_day = {}
    people = [""] + attendees
    earliest_m = to_min(earliest) if earliest else None
    latest_m = to_min(latest_end) if latest_end else None

    user_wh_start = 9 * 60
    user_wh_end = 17 * 60

    for day in days:
        per_person_busy = []
        ok = True
        for person in people:
            res = api.read_calendar(person, day)
            day_events = []
            if "days" in res:
                for d in res["days"]:
                    if d.get("day") == day or d.get("day", "").lower() == day.lower()[:3]:
                        day_events = d.get("events", [])
                        break
                if not day_events and len(res["days"]) == 1:
                    day_events = res["days"][0].get("events", [])
            per_person_busy.append(merge_busy(day_events))

        day_starts = []
        start_scan = user_wh_start
        if earliest_m is not None and earliest_m > start_scan:
            start_scan = earliest_m

        last_start = user_wh_end - minutes
        if latest_m is not None:
            lm = latest_m - minutes
            if lm < last_start:
                last_start = lm

        start_scan = ((start_scan + 14) // 15) * 15
        for s in range(start_scan, last_start + 1, 15):
            good = True
            for busy in per_person_busy:
                if not free_at(s, user_wh_end, busy):
                    good = False
                    break
            if good:
                day_starts.append(to_time(s))

        if day_starts:
            starts_by_day[day] = day_starts

    return {"starts": starts_by_day}
